use crate::terminal::{
    session::PtySessionConfig, PtyError, PtySession, PtySessionState, TerminalSignal,
};
use crate::worktree::WorktreeManager;
use parking_lot::{Mutex, RwLock};
use portable_pty::{native_pty_system, CommandBuilder, PtySize, PtySystem};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::mpsc;
use uuid::Uuid;

pub(crate) const LIFECYCLE_POLL_INTERVAL: Duration = Duration::from_millis(250);
const READER_SHUTDOWN_TIMEOUT: Duration = Duration::from_secs(2);

#[derive(Clone)]
pub struct PtyManager {
    sessions: Arc<RwLock<HashMap<String, Arc<PtySession>>>>,
    pty_system: Arc<Mutex<Box<dyn PtySystem + Send>>>,
}

impl Default for PtyManager {
    fn default() -> Self {
        Self::new()
    }
}

impl PtyManager {
    pub fn new() -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            pty_system: Arc::new(Mutex::new(native_pty_system())),
        }
    }

    pub fn spawn(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let session_id = Uuid::new_v4().to_string();
        let rx = self.spawn_with_id_and_worktree(session_id.clone(), cmd, cols, rows, None)?;
        Ok((session_id, rx))
    }

    pub fn spawn_shell(
        &self,
        cols: u16,
        rows: u16,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let cmd = CommandBuilder::new_default_prog();
        self.spawn(cmd, cols, rows)
    }

    /// Spawn an interactive terminal owned by `worktree_path`.
    ///
    /// Interactive PTYs are deliberately multi-session.  The worktree writer lease is an
    /// exclusive mutation/agent guard and must not be used to serialize terminal panes:
    /// Orca-style split panes require two or more live PTYs in the same worktree.
    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let session_id = Uuid::new_v4().to_string();
        let canonical_worktree = worktree_manager
            .canonical_allowed_path(worktree_path)
            .map_err(|error| PtyError::Other(error.to_string()))?;
        let rx = self.spawn_with_id_and_worktree(
            session_id.clone(),
            cmd,
            cols,
            rows,
            Some(canonical_worktree),
        )?;
        Ok((session_id, rx))
    }

    pub fn spawn_with_id(
        &self,
        session_id: impl Into<String>,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
    ) -> Result<mpsc::Receiver<Vec<u8>>, PtyError> {
        self.spawn_with_id_and_worktree(session_id.into(), cmd, cols, rows, None)
    }

    fn spawn_with_id_and_worktree(
        &self,
        session_id: String,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_path: Option<std::path::PathBuf>,
    ) -> Result<mpsc::Receiver<Vec<u8>>, PtyError> {
        if self.has_session(&session_id) {
            return Err(PtyError::Other(format!(
                "PTY session '{session_id}' already exists"
            )));
        }

        let pty_size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };

        let pair = {
            let pty_system = self.pty_system.lock();
            pty_system
                .openpty(pty_size)
                .map_err(|e| PtyError::PtyCreationError(e.to_string()))?
        };

        let reader = pair
            .master
            .try_clone_reader()
            .map_err(|e| PtyError::IoError(format!("Failed to clone reader: {e}")))?;

        let writer = pair
            .master
            .take_writer()
            .map_err(|e| PtyError::IoError(format!("Failed to take writer: {e}")))?;

        let child = pair
            .slave
            .spawn_command(cmd)
            .map_err(|e| PtyError::SpawnError(format!("Failed to spawn command: {e}")))?;

        drop(pair.slave);

        let (tx, rx) = mpsc::channel::<Vec<u8>>(1024);
        let session = Arc::new(PtySession::new(PtySessionConfig {
            id: session_id.clone(),
            master: pair.master,
            child,
            writer,
            reader,
            cols,
            rows,
            tx,
            worktree_path,
        }));

        self.sessions
            .write()
            .insert(session_id.clone(), Arc::clone(&session));
        session.mark_running();
        self.start_lifecycle_watcher(session_id);
        Ok(rx)
    }

    fn start_lifecycle_watcher(&self, session_id: String) {
        let manager = self.clone();
        tokio::spawn(async move {
            let Some(session) = manager.get_session(&session_id) else {
                return;
            };
            let mut reader_task = session.take_reader_task();

            loop {
                let Some(session) = manager.get_session(&session_id) else {
                    break;
                };

                match session.state() {
                    PtySessionState::Exited { .. } | PtySessionState::Failed { .. } => {
                        session.close_output();
                        manager.remove_from_registry(&session_id);
                        break;
                    }
                    PtySessionState::Closing => {
                        tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
                        continue;
                    }
                    PtySessionState::Starting | PtySessionState::Running => {}
                }

                match session.poll_exit_code() {
                    Ok(Some(code)) => {
                        manager.finalize_natural_exit(&session_id, code).await;
                        break;
                    }
                    Ok(None)
                        if session.output_receiver_closed() || session.is_reader_finished() =>
                    {
                        if let Err(error) = manager.close_session(&session_id).await {
                            tracing::debug!(
                                "PTY receiver-drop cleanup failed for {}: {}",
                                session_id,
                                error
                            );
                        }
                        break;
                    }
                    Ok(None) => {}
                    Err(error) => {
                        session.mark_failed(error.to_string());
                        session.close_io();
                        session.close_output();
                        manager.remove_from_registry(&session_id);
                        break;
                    }
                }

                if let Some(ref mut handle) = reader_task {
                    tokio::select! {
                        _ = handle => {
                            reader_task = None;
                        }
                        _ = tokio::time::sleep(LIFECYCLE_POLL_INTERVAL) => {}
                    }
                } else {
                    tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
                }
            }
        });
    }

    async fn finalize_natural_exit(&self, session_id: &str, code: i32) {
        let Some(session) = self.get_session(session_id) else {
            return;
        };
        if !session.begin_closing() {
            return;
        }

        session.close_io();
        let _ = Self::join_reader_bounded(&session).await;
        session.mark_exited(Some(code));
        session.close_output();
        self.remove_from_registry(session_id);
    }

    async fn join_reader_bounded(session: &Arc<PtySession>) -> Result<(), PtyError> {
        let Some(mut reader_task) = session.take_reader_task() else {
            return Ok(());
        };

        match tokio::time::timeout(READER_SHUTDOWN_TIMEOUT, &mut reader_task).await {
            Ok(Ok(())) => Ok(()),
            Ok(Err(error)) => Err(PtyError::Other(format!("PTY reader task failed: {error}"))),
            Err(_) => {
                reader_task.abort();
                Err(PtyError::Other(
                    "Timed out waiting for PTY reader shutdown".into(),
                ))
            }
        }
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        let Some(session) = self.get_session(session_id) else {
            return Ok(());
        };

        if !session.begin_closing() {
            if matches!(
                session.state(),
                PtySessionState::Exited { .. } | PtySessionState::Failed { .. }
            ) {
                session.close_output();
                self.remove_from_registry(session_id);
                return Ok(());
            }

            let deadline = tokio::time::Instant::now() + READER_SHUTDOWN_TIMEOUT;
            while tokio::time::Instant::now() < deadline {
                if !self.has_session(session_id) {
                    return Ok(());
                }
                tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
            }
            return Err(PtyError::Other(format!(
                "Timed out waiting for concurrent close of session '{session_id}'"
            )));
        }

        let mut first_error: Option<PtyError> = None;
        let mut exit_code = match session.poll_exit_code() {
            Ok(code) => code,
            Err(error) => {
                first_error = Some(error);
                None
            }
        };

        if exit_code.is_none() {
            if let Err(signal_error) = session.signal(TerminalSignal::Terminate) {
                if let Err(kill_error) = session.kill() {
                    first_error = Some(PtyError::KillError(format!(
                        "{signal_error}; fallback kill failed: {kill_error}"
                    )));
                }
            }
        }

        session.close_io();

        if let Err(reader_error) = Self::join_reader_bounded(&session).await {
            let _ = session
                .signal(TerminalSignal::Kill)
                .or_else(|_| session.kill());
            if first_error.is_none() {
                first_error = Some(reader_error);
            }
        }

        if exit_code.is_none() && !session.is_reaped() {
            let session_for_wait = Arc::clone(&session);
            match tokio::task::spawn_blocking(move || session_for_wait.wait_and_reap()).await {
                Ok(Ok(code)) => exit_code = code,
                Ok(Err(error)) => {
                    if first_error.is_none() {
                        first_error = Some(error);
                    }
                }
                Err(error) => {
                    if first_error.is_none() {
                        first_error = Some(PtyError::Other(format!(
                            "PTY child reap task failed: {error}"
                        )));
                    }
                }
            }
        }

        if let Some(error) = first_error {
            session.mark_failed(error.to_string());
            session.close_output();
            self.remove_from_registry(session_id);
            return Err(error);
        }

        session.mark_exited(exit_code);
        session.close_output();
        self.remove_from_registry(session_id);
        Ok(())
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.write_input(data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.resize(cols, rows)
    }

    pub fn kill(&self, session_id: &str) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.kill()
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.signal(signal)
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.sessions.read().get(session_id).cloned()
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }

    fn remove_from_registry(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.sessions.write().remove(session_id)
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.sessions.read().keys().cloned().collect()
    }

    pub fn session_count(&self) -> usize {
        self.sessions.read().len()
    }

    pub fn is_alive(&self, session_id: &str) -> Result<bool, PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        Ok(session.is_alive())
    }
}

use crate::terminal::output_hub::TerminalOutputHub;
use crate::terminal::{PtyError, PtyManager, PtySession, TerminalSignal};
use crate::worktree::manager::WorktreeManager;
use portable_pty::CommandBuilder;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct TerminalService {
    pty_manager: Arc<PtyManager>,
    output_hub: Arc<TerminalOutputHub>,
}

impl Default for TerminalService {
    fn default() -> Self {
        Self::new(
            Arc::new(PtyManager::new()),
            Arc::new(TerminalOutputHub::default()),
        )
    }
}

impl TerminalService {
    pub fn new(pty_manager: Arc<PtyManager>, output_hub: Arc<TerminalOutputHub>) -> Self {
        Self {
            pty_manager,
            output_hub,
        }
    }

    pub fn pty_manager(&self) -> &Arc<PtyManager> {
        &self.pty_manager
    }

    pub fn output_hub(&self) -> &Arc<TerminalOutputHub> {
        &self.output_hub
    }

    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, broadcast::Receiver<Vec<u8>>), PtyError> {
        let (session_id, mut pty_rx) =
            self.pty_manager
                .spawn_in_worktree(cmd, cols, rows, worktree_manager, worktree_path)?;

        let broadcast_rx = self.output_hub.register_session(&session_id);

        // Spawn output pump task from PTY reader to OutputHub
        let output_hub = Arc::clone(&self.output_hub);
        let session_id_clone = session_id.clone();
        tokio::spawn(async move {
            while let Some(chunk) = pty_rx.recv().await {
                output_hub.publish(&session_id_clone, chunk);
            }
        });

        Ok((session_id, broadcast_rx))
    }

    pub fn attach(
        &self,
        session_id: &str,
    ) -> Result<(Vec<u8>, broadcast::Receiver<Vec<u8>>), PtyError> {
        if !self
            .pty_manager
            .list_sessions()
            .contains(&session_id.to_string())
        {
            return Err(PtyError::SessionNotFound(session_id.to_string()));
        }

        self.output_hub
            .subscribe(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        self.pty_manager.write_input(session_id, data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        self.pty_manager.resize(session_id, cols, rows)
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        self.pty_manager.signal(session_id, signal)
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        self.output_hub.remove_session(session_id);
        self.pty_manager.close_session(session_id).await
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.pty_manager.list_sessions()
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.pty_manager.get_session(session_id)
    }
}

// allow: SIZE_OK — IPC module bundling terminal commands, output batching, and macOS libproc CWD resolution within constrained write scope
use crate::ipc::{run_blocking, IpcError};
use crate::terminal::{PtyError, PtySessionState, TerminalService, TerminalSignal};
use crate::worktree::{WorkspaceRegistry, WorktreeError, WorktreeIdentity};
use base64::{engine::general_purpose::STANDARD, Engine as _};
use parking_lot::Mutex;
use portable_pty::CommandBuilder;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tauri::{AppHandle, Emitter, Runtime, State};

pub const TERMINAL_OUTPUT_EVENT: &str = "terminal_output";
pub const TERMINAL_LIFECYCLE_EVENT: &str = "terminal_lifecycle";

const BATCH_FLUSH_INTERVAL: Duration = Duration::from_millis(10);
const BATCH_MAX_BYTES: usize = 32 * 1024;
const CWD_CACHE_TTL: Duration = Duration::from_millis(500);

static CWD_CACHE: Mutex<Option<HashMap<String, (Instant, PathBuf)>>> = Mutex::new(None);

pub fn get_cached_cwd(session_id: &str) -> Option<PathBuf> {
    let mut guard = CWD_CACHE.lock();
    let map = guard.as_mut()?;
    if let Some((cached_at, cwd)) = map.get(session_id) {
        if cached_at.elapsed() < CWD_CACHE_TTL {
            return Some(cwd.clone());
        }
        map.remove(session_id);
    }
    None
}

pub fn update_cached_cwd(session_id: String, cwd: PathBuf) {
    let mut guard = CWD_CACHE.lock();
    let map = guard.get_or_insert_with(HashMap::new);
    map.insert(session_id, (Instant::now(), cwd));
}

pub fn invalidate_cached_cwd(session_id: &str) {
    let mut guard = CWD_CACHE.lock();
    if let Some(map) = guard.as_mut() {
        map.remove(session_id);
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SpawnTerminalRequest {
    pub workspace_id: String,
    pub worktree: Option<WorktreeIdentity>,
    /// Optional inherited CWD for an Orca split/restore. The command validates that
    /// this path exists and remains inside the resolved worktree before spawning.
    pub cwd: Option<PathBuf>,
    pub cols: Option<u16>,
    pub rows: Option<u16>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SpawnTerminalResponse {
    pub session_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TerminalSessionSummary {
    pub session_id: String,
    pub worktree_path: Option<PathBuf>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TerminalCwdResponse {
    pub cwd: PathBuf,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TerminalOutputPayload {
    pub session_id: String,
    pub data: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TerminalLifecycleState {
    Started,
    Exited,
    Failed,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TerminalLifecyclePayload {
    pub session_id: String,
    pub state: TerminalLifecycleState,
    pub exit_code: Option<i32>,
    pub reason: Option<String>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TerminalSignalRequest {
    Interrupt,
    Terminate,
    Kill,
}

impl From<TerminalSignalRequest> for TerminalSignal {
    fn from(value: TerminalSignalRequest) -> Self {
        match value {
            TerminalSignalRequest::Interrupt => TerminalSignal::Interrupt,
            TerminalSignalRequest::Terminate => TerminalSignal::Terminate,
            TerminalSignalRequest::Kill => TerminalSignal::Kill,
        }
    }
}

fn flush_terminal_output<R: Runtime>(
    app: &AppHandle<R>,
    session_id: &str,
    buffer: &mut Vec<u8>,
) -> bool {
    if buffer.is_empty() {
        return true;
    }
    let payload = TerminalOutputPayload {
        session_id: session_id.to_string(),
        data: STANDARD.encode(&buffer),
    };
    buffer.clear();
    if let Err(error) = app.emit(TERMINAL_OUTPUT_EVENT, payload) {
        tracing::debug!("Failed to emit terminal output event: {error}");
        false
    } else {
        true
    }
}

#[tauri::command]
pub async fn cmd_terminal_spawn<R: Runtime>(
    app: AppHandle<R>,
    terminal_service: State<'_, Arc<TerminalService>>,
    registry: State<'_, WorkspaceRegistry>,
    request: SpawnTerminalRequest,
) -> Result<SpawnTerminalResponse, IpcError> {
    let cols = request.cols.unwrap_or(80);
    let rows = request.rows.unwrap_or(24);
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let requested_cwd = request.cwd.clone();

    let (worktree_manager, worktree_root) = run_blocking(move || {
        registry
            .resolve_terminal_target(&workspace_id, identity.as_ref())
            .map_err(IpcError::from)
    })
    .await?;

    let worktree_for_validation = worktree_manager.clone();
    let worktree_root_for_validation = worktree_root.clone();
    let cwd = run_blocking(move || {
        let Some(requested) = requested_cwd else {
            return Ok(worktree_root_for_validation);
        };
        let canonical = worktree_for_validation
            .canonical_allowed_path(&requested)
            .map_err(IpcError::from)?;
        if canonical != worktree_root_for_validation
            && !canonical.starts_with(&worktree_root_for_validation)
        {
            return Err(IpcError::from(WorktreeError::PathOutsideWorkspace {
                path: requested,
                root: worktree_root_for_validation,
            }));
        }
        if !canonical.is_dir() {
            return Err(IpcError::from(WorktreeError::InvalidPath {
                path: canonical,
                reason: "terminal cwd must be a directory".into(),
            }));
        }
        Ok(canonical)
    })
    .await?;

    let mut cmd = CommandBuilder::new_default_prog();
    cmd.cwd(&cwd);
    cmd.env("TERM", "xterm-256color");
    cmd.env("COLORTERM", "truecolor");
    cmd.env("PROMPT_EOL_MARK", "");
    for (key, default) in [
        ("LANG", "en_US.UTF-8"),
        ("LC_ALL", "en_US.UTF-8"),
        ("LC_CTYPE", "en_US.UTF-8"),
    ] {
        cmd.env(key, std::env::var(key).unwrap_or_else(|_| default.into()));
    }
    let (session_id, mut broadcast_rx) = terminal_service
        .spawn_in_worktree(cmd, cols, rows, &worktree_manager, &worktree_root)
        .map_err(IpcError::from)?;
    let session = terminal_service.get_session(&session_id).ok_or_else(|| {
        IpcError::internal(format!(
            "PTY session '{session_id}' disappeared during spawn"
        ))
    })?;

    let started = TerminalLifecyclePayload {
        session_id: session_id.clone(),
        state: TerminalLifecycleState::Started,
        exit_code: None,
        reason: None,
    };
    if let Err(error) = app.emit(TERMINAL_LIFECYCLE_EVENT, started) {
        let _ = terminal_service.close_session(&session_id).await;
        return Err(IpcError::internal(format!(
            "failed to emit terminal lifecycle event: {error}"
        )));
    }

    let session_id_clone = session_id.clone();
    let app_handle = app.clone();
    tokio::spawn(async move {
        let mut buffer = Vec::with_capacity(BATCH_MAX_BYTES);
        loop {
            if buffer.is_empty() {
                match broadcast_rx.recv().await {
                    Ok(chunk) => {
                        buffer.extend_from_slice(&chunk);
                        while buffer.len() < BATCH_MAX_BYTES {
                            match broadcast_rx.try_recv() {
                                Ok(next) => buffer.extend_from_slice(&next),
                                Err(_) => break,
                            }
                        }
                        if buffer.len() >= BATCH_MAX_BYTES
                            && !flush_terminal_output(&app_handle, &session_id_clone, &mut buffer)
                        {
                            break;
                        }
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(lag)) => {
                        tracing::warn!("Tauri desktop subscriber lagged by {lag} messages");
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                        break;
                    }
                }
            } else {
                tokio::select! {
                    res = broadcast_rx.recv() => {
                        match res {
                            Ok(chunk) => {
                                buffer.extend_from_slice(&chunk);
                                while buffer.len() < BATCH_MAX_BYTES {
                                    match broadcast_rx.try_recv() {
                                        Ok(next) => buffer.extend_from_slice(&next),
                                        Err(_) => break,
                                    }
                                }
                                if buffer.len() >= BATCH_MAX_BYTES
                                    && !flush_terminal_output(&app_handle, &session_id_clone, &mut buffer)
                                {
                                    break;
                                }
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Lagged(lag)) => {
                                tracing::warn!("Tauri desktop subscriber lagged by {lag} messages");
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                                let _ = flush_terminal_output(&app_handle, &session_id_clone, &mut buffer);
                                break;
                            }
                        }
                    }
                    _ = tokio::time::sleep(BATCH_FLUSH_INTERVAL) => {
                        if !flush_terminal_output(&app_handle, &session_id_clone, &mut buffer) {
                            break;
                        }
                    }
                }
            }
        }
        if !buffer.is_empty() {
            let _ = flush_terminal_output(&app_handle, &session_id_clone, &mut buffer);
        }

        for _ in 0..100 {
            let lifecycle = match session.state() {
                PtySessionState::Exited { code } => Some(TerminalLifecyclePayload {
                    session_id: session_id_clone.clone(),
                    state: TerminalLifecycleState::Exited,
                    exit_code: code,
                    reason: None,
                }),
                PtySessionState::Failed { reason } => Some(TerminalLifecyclePayload {
                    session_id: session_id_clone.clone(),
                    state: TerminalLifecycleState::Failed,
                    exit_code: None,
                    reason: Some(reason),
                }),
                PtySessionState::Starting | PtySessionState::Running | PtySessionState::Closing => {
                    None
                }
            };

            if let Some(payload) = lifecycle {
                if let Err(error) = app_handle.emit(TERMINAL_LIFECYCLE_EVENT, payload) {
                    tracing::debug!("Failed to emit terminal lifecycle event: {error}");
                }
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    });

    Ok(SpawnTerminalResponse { session_id })
}

#[tauri::command]
pub async fn cmd_terminal_get_cwd(
    terminal_service: State<'_, Arc<TerminalService>>,
    session_id: String,
) -> Result<TerminalCwdResponse, IpcError> {
    if let Some(cwd) = get_cached_cwd(&session_id) {
        return Ok(TerminalCwdResponse { cwd });
    }

    let session = terminal_service
        .get_session(&session_id)
        .ok_or_else(|| IpcError::from(PtyError::SessionNotFound(session_id.clone())))?;
    let pid = session.pid();
    let fallback = session.worktree_path();
    let sid = session_id.clone();
    let cwd = run_blocking(move || {
        let resolved = pid.and_then(process_cwd).or(fallback);
        resolved
            .map(|cwd| {
                update_cached_cwd(sid, cwd.clone());
                TerminalCwdResponse { cwd }
            })
            .ok_or_else(|| IpcError::internal("terminal cwd is unavailable"))
    })
    .await?;
    Ok(cwd)
}

#[cfg(target_os = "macos")]
mod macos_proc {
    use std::ffi::CStr;
    use std::path::PathBuf;

    const PROC_PIDVNODEPATHINFO: libc::c_int = 9;
    const MAXPATHLEN: usize = 1024;

    #[repr(C)]
    struct VinfoStat {
        vst_dev: u32,
        vst_mode: u16,
        vst_nlink: u16,
        vst_ino: u64,
        vst_uid: libc::uid_t,
        vst_gid: libc::gid_t,
        vst_atime: i64,
        vst_atimensec: i64,
        vst_mtime: i64,
        vst_mtimensec: i64,
        vst_ctime: i64,
        vst_ctimensec: i64,
        vst_birthtime: i64,
        vst_birthtimensec: i64,
        vst_size: libc::off_t,
        vst_blocks: i64,
        vst_blksize: i32,
        vst_flags: u32,
        vst_gen: u32,
        vst_rdev: u32,
        vst_qspare: [i64; 2],
    }

    #[repr(C)]
    struct VnodeInfo {
        vi_stat: VinfoStat,
        vi_type: libc::c_int,
        vi_pad: libc::c_int,
        vi_fsid: libc::fsid_t,
    }

    #[repr(C)]
    struct VnodeInfoPath {
        vip_vi: VnodeInfo,
        vip_path: [libc::c_char; MAXPATHLEN],
    }

    #[repr(C)]
    struct ProcVnodePathInfo {
        pvi_cdir: VnodeInfoPath,
        pvi_rdir: VnodeInfoPath,
    }

    extern "C" {
        fn proc_pidinfo(
            pid: libc::c_int,
            flavor: libc::c_int,
            arg: u64,
            buffer: *mut libc::c_void,
            buffersize: libc::c_int,
        ) -> libc::c_int;
    }

    pub fn get_proc_cwd(pid: u32) -> Option<PathBuf> {
        let mut info = std::mem::MaybeUninit::<ProcVnodePathInfo>::uninit();
        let size = std::mem::size_of::<ProcVnodePathInfo>() as libc::c_int;
        // SAFETY: proc_pidinfo safely writes up to `size` bytes into the uninit buffer.
        let ret = unsafe {
            proc_pidinfo(
                pid as libc::c_int,
                PROC_PIDVNODEPATHINFO,
                0,
                info.as_mut_ptr().cast(),
                size,
            )
        };
        if ret <= 0 {
            return None;
        }
        // SAFETY: proc_pidinfo succeeded (ret > 0) and initialized `info`.
        let info = unsafe { info.assume_init() };
        let path_bytes = &info.pvi_cdir.vip_path;
        let nul_pos = path_bytes.iter().position(|&c| c == 0)?;
        if nul_pos == 0 {
            return None;
        }
        let cstr = unsafe { CStr::from_ptr(path_bytes.as_ptr()) };
        cstr.to_str().ok().map(PathBuf::from)
    }
}

pub fn process_cwd(pid: u32) -> Option<PathBuf> {
    #[cfg(target_os = "linux")]
    {
        return std::fs::read_link(format!("/proc/{pid}/cwd")).ok();
    }

    #[cfg(target_os = "macos")]
    {
        if let Some(path) = macos_proc::get_proc_cwd(pid) {
            return Some(path);
        }
        let output = std::process::Command::new("/usr/sbin/lsof")
            .args(["-a", "-p", &pid.to_string(), "-d", "cwd", "-Fn"])
            .output()
            .ok()?;
        if !output.status.success() {
            return None;
        }
        let stdout = String::from_utf8(output.stdout).ok()?;
        return stdout
            .lines()
            .find_map(|line| line.strip_prefix('n'))
            .filter(|path| !path.is_empty())
            .map(PathBuf::from);
    }

    #[cfg(not(any(target_os = "linux", target_os = "macos")))]
    {
        let _ = pid;
        None
    }
}

