pub fn get_runtime_dir() -> PathBuf {
    let uid = unsafe { libc::getuid() };
    let path = PathBuf::from(format!("/tmp/rorca-{uid}"));
    let _ = fs::create_dir_all(&path);
    if let Ok(metadata) = fs::metadata(&path) {
        let mut permissions = metadata.permissions();
        permissions.set_mode(0o700);
        let _ = fs::set_permissions(&path, permissions);
    }
    path
}

pub fn get_socket_path() -> PathBuf {
    get_runtime_dir().join("daemon.sock")
}

pub fn get_lock_path() -> PathBuf {
    get_runtime_dir().join("daemon.lock")
}

pub fn get_default_session_path() -> PathBuf {
    if let Some(mut base) = dirs_next().or_else(dirs_fallback) {
        base.push("rorca");
        let _ = fs::create_dir_all(&base);
        base.join("session_state.json")
    } else {
        get_runtime_dir().join("session_state.json")
    }
}

fn dirs_next() -> Option<PathBuf> {
    #[cfg(target_os = "macos")]
    {
        std::env::var_os("HOME").map(|h| PathBuf::from(h).join("Library/Application Support"))
    }
    #[cfg(not(target_os = "macos"))]
    {
        std::env::var_os("XDG_DATA_HOME")
            .map(PathBuf::from)
            .or_else(|| std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".local/share")))
    }
}

fn dirs_fallback() -> Option<PathBuf> {
    std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".rorca"))
}

pub struct DaemonServer {
    terminal_service: Arc<TerminalService>,
    workspace_registry: WorkspaceRegistry,
    _remote_state: Arc<RemoteGatewayState>,
}

impl Default for DaemonServer {
    fn default() -> Self {
        Self::new()
    }
}

impl DaemonServer {
    pub fn new() -> Self {
        let pty_manager = Arc::new(PtyManager::new());
        let output_hub = Arc::new(TerminalOutputHub::default());
        let terminal_service = Arc::new(TerminalService::new(
            Arc::clone(&pty_manager),
            Arc::clone(&output_hub),
        ));
        let workspace_registry = WorkspaceRegistry::new();
        let remote_state = Arc::new(RemoteGatewayState::new(
            Arc::clone(&terminal_service),
            workspace_registry.clone(),
        ));

        // Start Axum remote gateway by default in daemon
        *remote_state.config.write() = RemoteGatewayConfig {
            mode: RemoteNetworkMode::LocalNetwork,
            port: 43821,
            allow_control: true,
        };
        let rs_clone = Arc::clone(&remote_state);
        tokio::spawn(async move {
            let _ = start_remote_server(rs_clone).await;
        });

        Self {
            terminal_service,
            workspace_registry,
            _remote_state: remote_state,
        }
    }

    pub async fn run_server(self: Arc<Self>) -> Result<(), String> {
        let socket_path = get_socket_path();
        let lock_path = get_lock_path();

        // Flock lock for atomic bind & stale socket recovery
        let lock_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&lock_path)
            .map_err(|e| format!("Failed to open lock file: {e}"))?;

        unsafe {
            use std::os::unix::io::AsRawFd;
            let fd = lock_file.as_raw_fd();
            if libc::flock(fd, libc::LOCK_EX | libc::LOCK_NB) != 0 {
                return Err("Another daemon instance is already holding the lock.".into());
            }
        }

        // Clean up stale socket if any
        if socket_path.exists() {
            let _ = fs::remove_file(&socket_path);
        }

        let listener = UnixListener::bind(&socket_path).map_err(|e| {
            format!(
                "Failed to bind UDS socket at {}: {e}",
                socket_path.display()
            )
        })?;

        // Ensure 0600 mode
        if let Ok(metadata) = fs::metadata(&socket_path) {
            let mut permissions = metadata.permissions();
            permissions.set_mode(0o600);
            let _ = fs::set_permissions(&socket_path, permissions);
        }

        tracing::info!("rorca daemon listening on {}", socket_path.display());

        loop {
            match listener.accept().await {
                Ok((stream, _)) => {
                    let server = Arc::clone(&self);
                    tokio::spawn(async move {
                        server.handle_client(stream).await;
                    });
                }
                Err(e) => {
                    tracing::error!("Daemon accept error: {e}");
                    break;
                }
            }
        }

        Ok(())
    }

    async fn handle_client(self: Arc<Self>, stream: UnixStream) {
        let (read_half, mut write_half) = stream.into_split();
        let mut reader = BufReader::new(read_half);
        let mut line = String::new();

        while let Ok(n) = reader.read_line(&mut line).await {
            if n == 0 {
                break;
            }
            let req: Result<DaemonRequest, _> = serde_json::from_str(line.trim());
            line.clear();

            let resp = match req {
                Ok(DaemonRequest::Handshake { version }) => {
                    if version != DAEMON_PROTOCOL_VERSION {
                        DaemonResponse::Error {
                            message: format!(
                                "Protocol version mismatch: expected {DAEMON_PROTOCOL_VERSION}, got {version}"
                            ),
                        }
                    } else {
                        DaemonResponse::HandshakeOk {
                            version: DAEMON_PROTOCOL_VERSION,
                            pid: std::process::id(),
                        }
                    }
                }
                Ok(DaemonRequest::Ping) => DaemonResponse::Pong,
                Ok(DaemonRequest::Spawn {
                    workspace_id,
                    worktree,
                    cols,
                    rows,
                }) => {
                    let res = self.handle_spawn(&workspace_id, worktree, cols, rows).await;
                    match res {
                        Ok(session_id) => DaemonResponse::SpawnOk { session_id },
                        Err(e) => DaemonResponse::Error { message: e },
                    }
                }
                Ok(DaemonRequest::Write { session_id, data }) => {
                    match self.terminal_service.write_input(&session_id, &data) {
                        Ok(()) => DaemonResponse::WriteOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Resize {
                    session_id,
                    cols,
                    rows,
                }) => match self.terminal_service.resize(&session_id, cols, rows) {
                    Ok(()) => DaemonResponse::ResizeOk,
                    Err(e) => DaemonResponse::Error {
                        message: e.to_string(),
                    },
                },
                Ok(DaemonRequest::Signal { session_id, signal }) => {
                    match self.terminal_service.signal(&session_id, signal) {
                        Ok(()) => DaemonResponse::SignalOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Close { session_id }) => {
                    match self.terminal_service.close_session(&session_id).await {
                        Ok(()) => DaemonResponse::CloseOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::ListSessions) => {
                    let sessions = self.terminal_service.list_sessions();
                    DaemonResponse::ListSessionsOk { sessions }
                }
                Ok(DaemonRequest::Attach { session_id }) => {
                    match self.terminal_service.attach(&session_id) {
                        Ok((history, rx)) => {
                            // Stream live PTY output as stream messages
                            let hub = Arc::clone(self.terminal_service.output_hub());
                            let mut write_clone = write_half; // will be handled
                                                              // Send initial attach ok
                            let resp = DaemonResponse::AttachOk { history };
                            let mut resp_json = serde_json::to_string(&resp).unwrap();
                            resp_json.push('\n');
                            let _ = write_clone.write_all(resp_json.as_bytes()).await;

                            // Pump output
                            Self::pump_stream(session_id, rx, hub, write_clone).await;
                            return;
                        }
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::SaveSession { session }) => {
                    let path = get_default_session_path();
                    let res =
                        tokio::task::spawn_blocking(move || save_session_to_path(&path, &session))
                            .await;
                    match res {
                        Ok(Ok(())) => DaemonResponse::SaveSessionOk,
                        Ok(Err(e)) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                        Err(e) => DaemonResponse::Error {
                            message: format!("Save session task panicked: {e}"),
                        },
                    }
                }
                Ok(DaemonRequest::LoadSession) => {
                    let path = get_default_session_path();
                    let res =
                        tokio::task::spawn_blocking(move || load_session_from_path(&path)).await;
                    match res {
                        Ok(Ok(session)) => DaemonResponse::LoadSessionOk { session },
                        Ok(Err(e)) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                        Err(e) => DaemonResponse::Error {
                            message: format!("Load session task panicked: {e}"),
                        },
                    }
                }
                Ok(DaemonRequest::ClearSession) => {
                    let path = get_default_session_path();
                    let res =
                        tokio::task::spawn_blocking(move || clear_session_from_path(&path)).await;
                    match res {
                        Ok(Ok(())) => DaemonResponse::ClearSessionOk,
                        Ok(Err(e)) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                        Err(e) => DaemonResponse::Error {
                            message: format!("Clear session task panicked: {e}"),
                        },
                    }
                }
                Ok(DaemonRequest::Shutdown) => {
                    std::process::exit(0);
                }
                Err(e) => DaemonResponse::Error {
                    message: format!("Malformed request: {e}"),
                },
            };

            let mut resp_json = serde_json::to_string(&resp).unwrap();
            resp_json.push('\n');
            if write_half.write_all(resp_json.as_bytes()).await.is_err() {
                break;
            }
        }
    }

    async fn handle_spawn(
        &self,
        workspace_id: &str,
        worktree: Option<crate::worktree::WorktreeIdentity>,
        cols: u16,
        rows: u16,
    ) -> Result<String, String> {
        let (mgr, cwd) = self
            .workspace_registry
            .resolve_terminal_target(workspace_id, worktree.as_ref())
            .map_err(|e| e.to_string())?;

        let mut cmd = CommandBuilder::new_default_prog();
        cmd.cwd(&cwd);

        let (session_id, _) = self
            .terminal_service
            .spawn_in_worktree(cmd, cols, rows, &mgr, &cwd)
            .map_err(|e| e.to_string())?;

        Ok(session_id)
    }

    async fn pump_stream(
        session_id: String,
        mut rx: broadcast::Receiver<Vec<u8>>,
        hub: Arc<TerminalOutputHub>,
        writer: tokio::net::unix::OwnedWriteHalf,
    ) {
        let mut writer = BufWriter::new(writer);
        loop {
            match rx.recv().await {
                Ok(data) => {
                    let msg = DaemonStreamMessage::Output {
                        session_id: Cow::Borrowed(&session_id),
                        data: Cow::Borrowed(&data),
                    };
                    let mut json = serde_json::to_string(&msg).unwrap();
                    json.push('\n');
                    if writer.write_all(json.as_bytes()).await.is_err() {
                        break;
                    }
                    if writer.flush().await.is_err() {
                        break;
                    }
                }
                Err(broadcast::error::RecvError::Lagged(_)) => {
                    // Resync with ringbuffer history snapshot
                    if let Some((history, new_rx)) = hub.subscribe(&session_id) {
                        rx = new_rx;
                        let msg = DaemonStreamMessage::Lagged {
                            session_id: Cow::Borrowed(&session_id),
                            history: Cow::Borrowed(&history),
                        };
                        let mut json = serde_json::to_string(&msg).unwrap();
                        json.push('\n');
                        if writer.write_all(json.as_bytes()).await.is_err() {
                            break;
                        }
                        if writer.flush().await.is_err() {
                            break;
                        }
                    }
                }
                Err(broadcast::error::RecvError::Closed) => {
                    let msg = DaemonStreamMessage::Exit {
                        session_id: Cow::Borrowed(&session_id),
                        exit_code: None,
                    };
                    let mut json = serde_json::to_string(&msg).unwrap();
                    json.push('\n');
                    let _ = writer.write_all(json.as_bytes()).await;
                    let _ = writer.flush().await;
                    break;
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_pump_stream_compact_framing_and_exit() {
        let (client_stream, server_stream) = UnixStream::pair().expect("unix pair");
        let (_server_read, server_write) = server_stream.into_split();
        let (client_read, _client_write) = client_stream.into_split();
        let mut client_reader = BufReader::new(client_read);

        let (tx, rx) = broadcast::channel(16);
        let hub = Arc::new(TerminalOutputHub::default());
        let session_id = "test-session-123".to_string();

        let pump_handle = tokio::spawn(DaemonServer::pump_stream(
            session_id.clone(),
            rx,
            hub,
            server_write,
        ));

        // Send binary output chunk
        tx.send(b"hello pty stream\n".to_vec()).unwrap();

        let mut line = String::new();
        client_reader.read_line(&mut line).await.unwrap();
        assert!(
            !line.contains('['),
            "Must not contain JSON number array: {line}"
        );
        assert!(
            line.contains(r#""data":"aGVsbG8gcHR5IHN0cmVhbQo=""#),
            "Expected base64 data: {line}"
        );
        assert!(line.contains(r#""sessionId":"test-session-123""#));

        // Close broadcast sender to trigger Exit
        drop(tx);
        line.clear();
        client_reader.read_line(&mut line).await.unwrap();
        assert!(line.contains(r#""type":"exit""#));
        assert!(line.contains(r#""sessionId":"test-session-123""#));

        let _ = pump_handle.await;
    }
}

use crate::session::PersistedWorkspaceSession;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use serde::{Deserialize, Serialize};
use std::borrow::Cow;

pub const DAEMON_PROTOCOL_VERSION: u32 = 1;

pub mod base64_serde {
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    use serde::{de::Error as _, Deserialize, Deserializer, Serializer};
    use std::borrow::Cow;

    pub fn serialize<S, T>(bytes: &T, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
        T: AsRef<[u8]>,
    {
        serializer.serialize_str(&STANDARD.encode(bytes.as_ref()))
    }

    pub fn deserialize<'de, D, T>(deserializer: D) -> Result<T, D::Error>
    where
        D: Deserializer<'de>,
        T: From<Vec<u8>>,
    {
        let s = Cow::<'de, str>::deserialize(deserializer)?;
        let decoded = STANDARD.decode(s.as_bytes()).map_err(D::Error::custom)?;
        Ok(T::from(decoded))
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonRequest {
    Handshake {
        version: u32,
    },
    Ping,
    Spawn {
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cols: u16,
        rows: u16,
    },
    Write {
        session_id: String,
        #[serde(with = "base64_serde")]
        data: Vec<u8>,
    },
    Resize {
        session_id: String,
        cols: u16,
        rows: u16,
    },
    Signal {
        session_id: String,
        signal: TerminalSignal,
    },
    Close {
        session_id: String,
    },
    ListSessions,
    Attach {
        session_id: String,
    },
    SaveSession {
        session: PersistedWorkspaceSession,
    },
    LoadSession,
    ClearSession,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonResponse {
    HandshakeOk {
        version: u32,
        pid: u32,
    },
    Pong,
    SpawnOk {
        session_id: String,
    },
    WriteOk,
    ResizeOk,
    SignalOk,
    CloseOk,
    ListSessionsOk {
        sessions: Vec<String>,
    },
    AttachOk {
        #[serde(with = "base64_serde")]
        history: Vec<u8>,
    },
    SaveSessionOk,
    LoadSessionOk {
        session: Option<PersistedWorkspaceSession>,
    },
    ClearSessionOk,
    Error {
        message: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonStreamMessage<'a> {
    Output {
        session_id: Cow<'a, str>,
        #[serde(with = "base64_serde")]
        data: Cow<'a, [u8]>,
    },
    Lagged {
        session_id: Cow<'a, str>,
        #[serde(with = "base64_serde")]
        history: Cow<'a, [u8]>,
    },
    Exit {
        session_id: Cow<'a, str>,
        exit_code: Option<i32>,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_daemon_stream_message_compact_base64_encoding() {
        let output = DaemonStreamMessage::Output {
            session_id: Cow::Borrowed("s1"),
            data: Cow::Borrowed(b"hello world"),
        };
        let json = serde_json::to_string(&output).expect("serialize output");

        // Contract: must NOT serialize raw bytes as JSON number arrays [104, 101, ...]
        assert!(
            !json.contains('['),
            "Stream output must not contain JSON number arrays: {json}"
        );
        assert!(
            json.contains(r#""data":"aGVsbG8gd29ybGQ=""#),
            "Expected base64-encoded string for data: {json}"
        );

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize output");
        match deserialized {
            DaemonStreamMessage::Output { session_id, data } => {
                assert_eq!(session_id, "s1");
                assert_eq!(&data[..], b"hello world");
            }
            _ => panic!("Expected Output variant"),
        }
    }

    #[test]
    fn test_daemon_stream_message_lagged_and_exit_roundtrip() {
        let lagged = DaemonStreamMessage::Lagged {
            session_id: Cow::Borrowed("s2"),
            history: Cow::Borrowed(b"history bytes"),
        };
        let json = serde_json::to_string(&lagged).expect("serialize lagged");
        assert!(!json.contains('['));
        assert!(json.contains(r#""history":"aGlzdG9yeSBieXRlcw==""#));

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize lagged");
        assert_eq!(
            deserialized,
            DaemonStreamMessage::Lagged {
                session_id: Cow::Owned("s2".to_string()),
                history: Cow::Owned(b"history bytes".to_vec()),
            }
        );

        let exit = DaemonStreamMessage::Exit {
            session_id: Cow::Borrowed("s3"),
            exit_code: Some(0),
        };
        let exit_json = serde_json::to_string(&exit).expect("serialize exit");
        let deserialized_exit: DaemonStreamMessage =
            serde_json::from_str(&exit_json).expect("deserialize exit");
        assert_eq!(
            deserialized_exit,
            DaemonStreamMessage::Exit {
                session_id: Cow::Owned("s3".to_string()),
                exit_code: Some(0),
            }
        );
    }

    #[test]
    fn test_daemon_request_write_and_response_attach_base64() {
        let write_req = DaemonRequest::Write {
            session_id: "term-1".to_string(),
            data: b"ls -la\n".to_vec(),
        };
        let json = serde_json::to_string(&write_req).expect("serialize write");
        assert!(!json.contains('['));
        assert!(json.contains(r#""data":"bHMgLWxhCg==""#));

        let deserialized_req: DaemonRequest =
            serde_json::from_str(&json).expect("deserialize write");
        match deserialized_req {
            DaemonRequest::Write { session_id, data } => {
                assert_eq!(session_id, "term-1");
                assert_eq!(data, b"ls -la\n");
            }
            _ => panic!("Expected Write variant"),
        }

        let attach_resp = DaemonResponse::AttachOk {
            history: b"initial prompt $ ".to_vec(),
        };
        let resp_json = serde_json::to_string(&attach_resp).expect("serialize attach resp");
        assert!(!resp_json.contains('['));
        assert!(resp_json.contains(r#""history":"aW5pdGlhbCBwcm9tcHQgJCA="#));

        let deserialized_resp: DaemonResponse =
            serde_json::from_str(&resp_json).expect("deserialize attach resp");
        match deserialized_resp {
            DaemonResponse::AttachOk { history } => {
                assert_eq!(history, b"initial prompt $ ");
            }
            _ => panic!("Expected AttachOk variant"),
        }
    }
}

use parking_lot::RwLock;
use rand::{distributions::Alphanumeric, Rng};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, Instant};

const PAIRING_EXPIRY: Duration = Duration::from_secs(60);
const LAST_SEEN_PERSIST_INTERVAL: Duration = Duration::from_secs(60);

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum DevicePermission {
    View,
    Control,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DeviceInfo {
    pub id: String,
    pub name: String,
    pub permission: DevicePermission,
    pub created_at: u64,
    pub last_seen_at: u64,
    pub revoked: bool,
}

struct PairingCode {
    _code: String,
    created_at: Instant,
    default_permission: DevicePermission,
}

#[derive(Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct PersistedAuthState {
    devices: HashMap<String, DeviceInfo>,
    tokens: HashMap<String, String>,
}

#[derive(Clone)]
pub struct AuthManager {
    pairing_codes: Arc<RwLock<HashMap<String, PairingCode>>>,
    devices: Arc<RwLock<HashMap<String, DeviceInfo>>>,
    tokens: Arc<RwLock<HashMap<String, String>>>,
    persistence_path: Option<PathBuf>,
    last_persisted_at: Arc<RwLock<Instant>>,
}

impl Default for AuthManager {
    fn default() -> Self {
        Self::new()
    }
}

impl AuthManager {
    pub fn new() -> Self {
        Self::with_persistence(None)
    }

    pub fn with_persistence(persistence_path: Option<PathBuf>) -> Self {
        let persisted = persistence_path
            .as_deref()
            .and_then(load_persisted_auth)
            .unwrap_or_default();
        Self {
            pairing_codes: Arc::new(RwLock::new(HashMap::new())),
            devices: Arc::new(RwLock::new(persisted.devices)),
            tokens: Arc::new(RwLock::new(persisted.tokens)),
            persistence_path,
            last_persisted_at: Arc::new(RwLock::new(Instant::now())),
        }
    }

    pub fn create_pairing_code(&self, default_permission: DevicePermission) -> String {
        let pin: u32 = rand::thread_rng().gen_range(100_000..=999_999);
        let code = format!("{pin:06}");

        self.pairing_codes.write().insert(
            code.clone(),
            PairingCode {
                _code: code.clone(),
                created_at: Instant::now(),
                default_permission,
            },
        );
        code
    }

    pub fn exchange_pairing_code(
        &self,
        code: &str,
        device_name: &str,
    ) -> Result<(String, DeviceInfo), AuthError> {
        let mut codes = self.pairing_codes.write();
        let pairing = codes.remove(code).ok_or(AuthError::InvalidPairingCode)?;
        drop(codes);

        if pairing.created_at.elapsed() > PAIRING_EXPIRY {
            return Err(AuthError::ExpiredPairingCode);
        }

        let device_id = uuid::Uuid::new_v4().to_string();
        let token: String = rand::thread_rng()
            .sample_iter(&Alphanumeric)
            .take(64)
            .map(char::from)
            .collect();

        let now = unix_now();
        let info = DeviceInfo {
            id: device_id.clone(),
            name: device_name.to_string(),
            permission: pairing.default_permission,
            created_at: now,
            last_seen_at: now,
            revoked: false,
        };

        self.devices.write().insert(device_id.clone(), info.clone());
        self.tokens.write().insert(token.clone(), device_id);
        self.persist_best_effort();
        Ok((token, info))
    }

    pub fn validate_token(&self, token: &str) -> Result<DeviceInfo, AuthError> {
        let device_id = {
            let tokens = self.tokens.read();
            tokens.get(token).cloned()
        }
        .ok_or(AuthError::Unauthorized)?;

        let result = {
            let mut devices = self.devices.write();
            let device = devices.get_mut(&device_id).ok_or(AuthError::Unauthorized)?;
            if device.revoked {
                return Err(AuthError::RevokedDevice);
            }
            device.last_seen_at = unix_now();
            device.clone()
        };

        let should_persist = self.last_persisted_at.read().elapsed() >= LAST_SEEN_PERSIST_INTERVAL;
        if should_persist {
            self.persist_best_effort();
        }

        Ok(result)
    }

    pub fn list_devices(&self) -> Vec<DeviceInfo> {
        self.devices.read().values().cloned().collect()
    }

    pub fn revoke_device(&self, device_id: &str) -> bool {
        let changed = {
            let mut devices = self.devices.write();
            if let Some(device) = devices.get_mut(device_id) {
                device.revoked = true;
                true
            } else {
                false
            }
        };
        if changed {
            self.persist_best_effort();
        }
        changed
    }

    #[cfg(test)]
    pub(crate) fn set_last_persisted_at(&self, instant: Instant) {
        *self.last_persisted_at.write() = instant;
    }

    fn persist_best_effort(&self) {
        let Some(path) = self.persistence_path.as_deref() else {
            return;
        };
        *self.last_persisted_at.write() = Instant::now();
        let snapshot = PersistedAuthState {
            devices: self.devices.read().clone(),
            tokens: self.tokens.read().clone(),
        };
        if let Err(error) = write_private_json(path, &snapshot) {
            tracing::warn!("failed to persist remote auth state: {error}");
        }
    }
}

fn unix_now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn load_persisted_auth(path: &Path) -> Option<PersistedAuthState> {
    let bytes = std::fs::read(path).ok()?;
    serde_json::from_slice(&bytes).ok()
}

pub(crate) fn write_private_json<T: Serialize>(path: &Path, value: &T) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(parent, std::fs::Permissions::from_mode(0o700));
        }
    }
    let temp = path.with_extension("tmp");
    let bytes = serde_json::to_vec_pretty(value)
        .map_err(|error| std::io::Error::new(std::io::ErrorKind::InvalidData, error))?;
    std::fs::write(&temp, bytes)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&temp, std::fs::Permissions::from_mode(0o600));
    }
    std::fs::rename(temp, path)?;
    Ok(())
}

#[derive(Debug, thiserror::Error)]
pub enum AuthError {
    #[error("Invalid pairing code")]
    InvalidPairingCode,
    #[error("Pairing code has expired")]
    ExpiredPairingCode,
    #[error("Unauthorized access")]
    Unauthorized,
    #[error("Device access has been revoked")]
    RevokedDevice,
}

#[cfg(test)]
mod persistence_tests {
    use super::*;

    #[test]
    fn paired_devices_and_revocations_survive_reopen() {
        let dir = tempfile::TempDir::new().expect("tempdir");
        let path = dir.path().join("remote-auth.json");
        let manager = AuthManager::with_persistence(Some(path.clone()));
        let code = manager.create_pairing_code(DevicePermission::Control);
        let (token, device) = manager.exchange_pairing_code(&code, "Phone").expect("pair");
        assert!(manager.revoke_device(&device.id));

        let reopened = AuthManager::with_persistence(Some(path));
        let listed = reopened.list_devices();
        assert_eq!(listed.len(), 1);
        assert!(listed[0].revoked);
        assert!(matches!(
            reopened.validate_token(&token),
            Err(AuthError::RevokedDevice)
        ));
    }

    #[test]
    fn validate_token_throttles_disk_persistence() {
        let dir = tempfile::TempDir::new().expect("tempdir");
        let path = dir.path().join("remote-auth.json");
        let manager = AuthManager::with_persistence(Some(path.clone()));
        let code = manager.create_pairing_code(DevicePermission::Control);
        let (token, device) = manager.exchange_pairing_code(&code, "Phone").expect("pair");
        assert!(path.exists(), "pairing must persist immediately");

        // Remove the file on disk to observe whether validate_token writes to disk
        std::fs::remove_file(&path).expect("remove file");
        assert!(!path.exists());

        // Validating token right after pairing must not rewrite to disk (<60s)
        let validated = manager.validate_token(&token).expect("validate");
        assert_eq!(validated.name, "Phone");
        assert!(
            !path.exists(),
            "validate_token must not persist to disk on every request"
        );

        // When >= 60s have elapsed since last persist, validate_token flushes to disk
        manager.set_last_persisted_at(
            Instant::now()
                .checked_sub(Duration::from_secs(65))
                .expect("instant subtraction"),
        );
        let validated_after = manager
            .validate_token(&token)
            .expect("validate after interval");
        assert_eq!(validated_after.name, "Phone");
        assert!(
            path.exists(),
            "validate_token must persist to disk once >=60s has elapsed"
        );

        // Revoking must persist immediately
        std::fs::remove_file(&path).expect("remove file before revoke");
        assert!(!path.exists());
        assert!(manager.revoke_device(&device.id));
        assert!(path.exists(), "revoke_device must persist immediately");
    }
}

