use tauri::Url;
use thiserror::Error;

#[derive(Debug, Error, Clone, PartialEq)]
pub enum BrowserError {
    #[error("Browser not found: {0}")]
    NotFound(String),
    #[error("Invalid URL: {0}")]
    InvalidUrl(String),
    #[error("Scheme denied for URL: {0} (only http, https, and about:blank allowed)")]
    SchemeDenied(String),
    #[error("Invalid bounds provided")]
    InvalidBounds,
    #[error("Unsupported profile: {0}")]
    UnsupportedProfile(String),
    #[error("Failed to create browser webview: {0}")]
    CreateFailed(String),
    #[error("Navigation failed: {0}")]
    NavigationFailed(String),
    #[error("History navigation failed: {0}")]
    HistoryFailed(String),
    #[error("Failed to close browser: {0}")]
    CloseFailed(String),
    #[error("Platform unsupported: {0}")]
    PlatformUnsupported(String),
    #[error("Internal browser error: {0}")]
    Internal(String),
}

pub fn validate_url(url_str: &str) -> Result<String, BrowserError> {
    let trimmed = url_str.trim();
    if trimmed.is_empty() {
        return Ok("about:blank".to_string());
    }
    if trimmed == "about:blank" {
        return Ok(trimmed.to_string());
    }

    let parsed = Url::parse(trimmed).map_err(|e| BrowserError::InvalidUrl(e.to_string()))?;
    match parsed.scheme() {
        "http" | "https" => Ok(parsed.to_string()),
        "about" if parsed.path() == "blank" => Ok("about:blank".to_string()),
        _ => Err(BrowserError::SchemeDenied(parsed.to_string())),
    }
}

use crate::browser::BrowserError;
use serde::Deserialize;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ImportedCookie {
    pub name: String,
    pub value: String,
    pub domain: Option<String>,
    pub path: String,
    pub secure: bool,
    pub http_only: bool,
    pub expires_unix: Option<i64>,
    pub same_site: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct JsonCookie {
    name: String,
    #[serde(default)]
    value: String,
    #[serde(default, alias = "host")]
    domain: Option<String>,
    #[serde(default)]
    path: Option<String>,
    #[serde(default)]
    secure: bool,
    #[serde(default, alias = "http_only")]
    http_only: bool,
    #[serde(default, alias = "expirationDate", alias = "expiration_date", alias = "expires")]
    expiration_date: Option<f64>,
    #[serde(default, alias = "same_site")]
    same_site: Option<String>,
}

fn from_json_cookie(cookie: JsonCookie) -> Result<ImportedCookie, BrowserError> {
    let name = cookie.name.trim().to_string();
    if name.is_empty() {
        return Err(BrowserError::CookieImport("cookie name cannot be empty".into()));
    }
    Ok(ImportedCookie {
        name,
        value: cookie.value,
        domain: cookie.domain.map(|value| value.trim().to_string()).filter(|value| !value.is_empty()),
        path: cookie.path.filter(|value| value.starts_with('/')).unwrap_or_else(|| "/".into()),
        secure: cookie.secure,
        http_only: cookie.http_only,
        expires_unix: cookie.expiration_date.and_then(|value| {
            if value.is_finite() && value > 0.0 { Some(value.floor() as i64) } else { None }
        }),
        same_site: cookie.same_site.map(|value| value.to_ascii_lowercase()),
    })
}

fn parse_json(input: &str) -> Result<Vec<ImportedCookie>, BrowserError> {
    let value: serde_json::Value = serde_json::from_str(input)
        .map_err(|error| BrowserError::CookieImport(format!("invalid JSON cookie file: {error}")))?;
    let cookie_values = match value {
        serde_json::Value::Array(values) => values,
        serde_json::Value::Object(mut object) => object
            .remove("cookies")
            .and_then(|value| value.as_array().cloned())
            .ok_or_else(|| BrowserError::CookieImport("JSON must be an array or contain a cookies array".into()))?,
        _ => return Err(BrowserError::CookieImport("JSON cookie file must contain an array".into())),
    };
    cookie_values
        .into_iter()
        .map(|value| {
            serde_json::from_value::<JsonCookie>(value)
                .map_err(|error| BrowserError::CookieImport(format!("invalid cookie entry: {error}")))
                .and_then(from_json_cookie)
        })
        .collect()
}

fn parse_netscape(input: &str) -> Result<Vec<ImportedCookie>, BrowserError> {
    let mut cookies = Vec::new();
    for (line_number, raw_line) in input.lines().enumerate() {
        let mut line = raw_line.trim();
        if line.is_empty() || (line.starts_with('#') && !line.starts_with("#HttpOnly_")) {
            continue;
        }
        let mut http_only = false;
        if let Some(rest) = line.strip_prefix("#HttpOnly_") {
            http_only = true;
            line = rest;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        if fields.len() < 7 {
            return Err(BrowserError::CookieImport(format!(
                "invalid Netscape cookie line {}: expected 7 tab-separated fields",
                line_number + 1
            )));
        }
        let name = fields[5].trim();
        if name.is_empty() {
            return Err(BrowserError::CookieImport(format!("empty cookie name on line {}", line_number + 1)));
        }
        let expires_unix = fields[4].trim().parse::<i64>().ok().filter(|value| *value > 0);
        cookies.push(ImportedCookie {
            name: name.to_string(),
            value: fields[6].to_string(),
            domain: Some(fields[0].trim().to_string()).filter(|value| !value.is_empty()),
            path: if fields[2].starts_with('/') { fields[2].to_string() } else { "/".into() },
            secure: fields[3].eq_ignore_ascii_case("TRUE"),
            http_only,
            expires_unix,
            same_site: None,
        });
    }
    Ok(cookies)
}

pub fn parse_cookie_file(input: &str) -> Result<Vec<ImportedCookie>, BrowserError> {
    let trimmed = input.trim_start();
    let cookies = if trimmed.starts_with('[') || trimmed.starts_with('{') {
        parse_json(input)?
    } else {
        parse_netscape(input)?
    };
    if cookies.is_empty() {
        return Err(BrowserError::CookieImport("cookie file did not contain any cookies".into()));
    }
    Ok(cookies)
}

use crate::browser::model::*;
use crate::browser::security::{validate_url, BrowserError};
use parking_lot::RwLock;
use std::collections::HashMap;
use std::sync::Arc;
use uuid::Uuid;

#[derive(Debug)]
pub struct ManagedBrowserSession {
    pub browser_id: String,
    pub webview_label: String,
    pub workspace_id: Option<String>,
    pub worktree_path: Option<String>,
    pub profile_id: BrowserProfileId,
    pub generation: u64,
    pub url: String,
    pub title: Option<String>,
    pub loading: bool,
    pub can_go_back: bool,
    pub can_go_forward: bool,
    pub zoom_factor: f64,
    pub load_error: Option<String>,
    pub visible: bool,
    pub bounds: Option<LogicalRect>,
}

#[derive(Default, Clone)]
pub struct BrowserManager {
    sessions: Arc<RwLock<HashMap<String, ManagedBrowserSession>>>,
}

impl BrowserManager {
    pub fn new() -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub fn register_session(
        &self,
        req: CreateBrowserRequest,
    ) -> Result<BrowserState, BrowserError> {
        let valid_url = validate_url(&req.url)?;
        if let Some(ref bounds) = req.bounds {
            if !bounds.is_valid() {
                return Err(BrowserError::InvalidBounds);
            }
        }

        let uuid = Uuid::new_v4().to_string();
        let browser_id = uuid.clone();
        let webview_label = format!("browser-{}", uuid);
        let profile_id = req.profile.unwrap_or(BrowserProfileId::Default);
        let visible = req.visible.unwrap_or(true);

        let session = ManagedBrowserSession {
            browser_id: browser_id.clone(),
            webview_label: webview_label.clone(),
            workspace_id: req.workspace_id,
            worktree_path: req.worktree_path,
            profile_id: profile_id.clone(),
            generation: 1,
            url: valid_url.clone(),
            title: None,
            loading: false,
            can_go_back: false,
            can_go_forward: false,
            zoom_factor: 1.0,
            load_error: None,
            visible,
            bounds: req.bounds,
        };

        let state = BrowserState {
            browser_id: session.browser_id.clone(),
            webview_label: session.webview_label.clone(),
            workspace_id: session.workspace_id.clone(),
            worktree_path: session.worktree_path.clone(),
            profile_id,
            generation: session.generation,
            url: session.url.clone(),
            title: None,
            loading: session.loading,
            can_go_back: session.can_go_back,
            can_go_forward: session.can_go_forward,
            zoom_factor: session.zoom_factor,
            load_error: None,
            visible: session.visible,
        };

        self.sessions.write().insert(browser_id, session);
        Ok(state)
    }

    pub fn get_state(&self, browser_id: &str) -> Result<BrowserState, BrowserError> {
        let guard = self.sessions.read();
        let s = guard
            .get(browser_id)
            .ok_or_else(|| BrowserError::NotFound(browser_id.to_string()))?;

        Ok(BrowserState {
            browser_id: s.browser_id.clone(),
            webview_label: s.webview_label.clone(),
            workspace_id: s.workspace_id.clone(),
            worktree_path: s.worktree_path.clone(),
            profile_id: s.profile_id.clone(),
            generation: s.generation,
            url: s.url.clone(),
            title: s.title.clone(),
            loading: s.loading,
            can_go_back: s.can_go_back,
            can_go_forward: s.can_go_forward,
            zoom_factor: s.zoom_factor,
            load_error: s.load_error.clone(),
            visible: s.visible,
        })
    }

    pub fn update_url(&self, browser_id: &str, new_url: &str) -> Result<String, BrowserError> {
        let valid_url = validate_url(new_url)?;
        let mut guard = self.sessions.write();
        let s = guard
            .get_mut(browser_id)
            .ok_or_else(|| BrowserError::NotFound(browser_id.to_string()))?;

        s.url = valid_url.clone();
        s.generation += 1;
        s.loading = true;
        s.load_error = None;
        Ok(valid_url)
    }

    pub fn set_bounds(&self, browser_id: &str, bounds: LogicalRect) -> Result<(), BrowserError> {
        if !bounds.is_valid() {
            return Err(BrowserError::InvalidBounds);
        }
        let mut guard = self.sessions.write();
        let s = guard
            .get_mut(browser_id)
            .ok_or_else(|| BrowserError::NotFound(browser_id.to_string()))?;
        s.bounds = Some(bounds);
        Ok(())
    }

    pub fn set_visible(&self, browser_id: &str, visible: bool) -> Result<(), BrowserError> {
        let mut guard = self.sessions.write();
        let s = guard
            .get_mut(browser_id)
            .ok_or_else(|| BrowserError::NotFound(browser_id.to_string()))?;
        s.visible = visible;
        Ok(())
    }

    pub fn set_zoom(&self, browser_id: &str, zoom: f64) -> Result<f64, BrowserError> {
        let clamped = zoom.clamp(0.25, 5.0);
        let mut guard = self.sessions.write();
        let s = guard
            .get_mut(browser_id)
            .ok_or_else(|| BrowserError::NotFound(browser_id.to_string()))?;
        s.zoom_factor = clamped;
        Ok(clamped)
    }

    #[allow(clippy::too_many_arguments)]
    pub fn update_navigation_state(
        &self,
        browser_id: &str,
        url: Option<String>,
        title: Option<String>,
        loading: Option<bool>,
        can_go_back: Option<bool>,
        can_go_forward: Option<bool>,
        error: Option<String>,
    ) -> Result<BrowserState, BrowserError> {
        let mut guard = self.sessions.write();
        let s = guard
            .get_mut(browser_id)
            .ok_or_else(|| BrowserError::NotFound(browser_id.to_string()))?;

        if let Some(u) = url {
            s.url = u;
        }
        if let Some(t) = title {
            s.title = Some(t);
        }
        if let Some(l) = loading {
            s.loading = l;
        }
        if let Some(b) = can_go_back {
            s.can_go_back = b;
        }
        if let Some(f) = can_go_forward {
            s.can_go_forward = f;
        }
        s.load_error = error;

        Ok(BrowserState {
            browser_id: s.browser_id.clone(),
            webview_label: s.webview_label.clone(),
            workspace_id: s.workspace_id.clone(),
            worktree_path: s.worktree_path.clone(),
            profile_id: s.profile_id.clone(),
            generation: s.generation,
            url: s.url.clone(),
            title: s.title.clone(),
            loading: s.loading,
            can_go_back: s.can_go_back,
            can_go_forward: s.can_go_forward,
            zoom_factor: s.zoom_factor,
            load_error: s.load_error.clone(),
            visible: s.visible,
        })
    }

    pub fn remove_session(&self, browser_id: &str) -> Option<ManagedBrowserSession> {
        self.sessions.write().remove(browser_id)
    }

    pub fn list_sessions(&self) -> Vec<BrowserSessionSummary> {
        let guard = self.sessions.read();
        guard
            .values()
            .map(|s| BrowserSessionSummary {
                browser_id: s.browser_id.clone(),
                webview_label: s.webview_label.clone(),
                workspace_id: s.workspace_id.clone(),
                url: s.url.clone(),
                title: s.title.clone(),
                visible: s.visible,
            })
            .collect()
    }
}

