import type {
  Worktree,
  WorktreeIdentity,
} from "./types";
import type { RegisteredProject } from "./tauri";

const TOKEN_KEY = "ferryx_remote_token";

export function getRemoteAuthToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setRemoteAuthToken(token: string) {
  localStorage.setItem(TOKEN_KEY, token);
}

export function clearRemoteAuthToken() {
  localStorage.removeItem(TOKEN_KEY);
}

export class RemoteClient {
  private baseUrl: string;
  private ws: WebSocket | null = null;
  private eventListeners: Map<string, Set<(payload: any) => void>> = new Map();
  private reconnectTimer: any = null;

  constructor(baseUrl: string = window.location.origin) {
    this.baseUrl = baseUrl.replace(/\/$/, "");
  }

  private authHeader(): Record<string, string> {
    const token = getRemoteAuthToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
  }

  async fetchJson<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const res = await fetch(`${this.baseUrl}${endpoint}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...this.authHeader(),
        ...(options.headers || {}),
      },
    });
    if (!res.ok) {
      if (res.status === 401) {
        clearRemoteAuthToken();
      }
      throw new Error(`Remote API error ${res.status}: ${await res.text()}`);
    }
    return res.json();
  }

  async getWorkspaceState(): Promise<{
    projects: RegisteredProject[];
    activeWorkspaceId: string;
    worktrees: Worktree[];
    sessions: Array<{ sessionId: string; running: boolean }>;
  }> {
    return this.fetchJson("/api/v1/workspace/state");
  }

  async listWorktrees(_workspaceId: string): Promise<Worktree[]> {
    const state = await this.getWorkspaceState();
    return state.worktrees || [];
  }

  async createWorktree(request: {
    workspaceId: string;
    worktree: WorktreeIdentity;
    baseRef?: string | null;
  }): Promise<Worktree> {
    return this.fetchJson("/api/v1/workspace/worktrees", {
      method: "POST",
      body: JSON.stringify(request),
    });
  }

  async deleteWorktree(request: {
    workspaceId: string;
    worktree: WorktreeIdentity;
    deleteBranch?: boolean | null;
  }): Promise<void> {
    await this.fetchJson("/api/v1/workspace/worktrees", {
      method: "DELETE",
      body: JSON.stringify(request),
    });
  }

  async spawnTerminal(_request: {
    workspaceId: string;
    worktree?: WorktreeIdentity | null;
    cols?: number;
    rows?: number;
  }): Promise<{ sessionId: string }> {
    // In remote mode, sessions are live on desktop; we attach or spawn
    return { sessionId: `remote-${Date.now()}` };
  }

  connectEvents() {
    if (this.ws || !getRemoteAuthToken()) return;
    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    const token = getRemoteAuthToken();
    const wsUrl = `${protocol}//${window.location.host}/api/v1/events?token=${encodeURIComponent(token || "")}`;

    try {
      this.ws = new WebSocket(wsUrl);
      this.ws.onmessage = (ev) => {
        try {
          const msg = JSON.parse(ev.data);
          const listeners = this.eventListeners.get(msg.event);
          if (listeners) {
            for (const fn of listeners) {
              fn(msg.payload);
            }
          }
        } catch {
          // ignore
        }
      };

      this.ws.onclose = () => {
        this.ws = null;
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = setTimeout(() => this.connectEvents(), 3000);
      };
    } catch {
      // ignore
    }
  }

  listen(event: string, handler: (payload: any) => void): () => void {
    const listeners = this.eventListeners.get(event) ?? new Set();
    listeners.add(handler);
    this.eventListeners.set(event, listeners);
    this.connectEvents();

    return () => {
      listeners.delete(handler);
    };
  }
}

export const defaultRemoteClient = new RemoteClient();

import type { TerminalAttachment, TerminalTransport, Unsubscribe } from "./types";

export class WebSocketTerminalTransport implements TerminalTransport {
  private baseUrl: string;
  private token: string;
  private sockets: Map<string, WebSocket> = new Map();
  private outputListeners: Map<string, Set<(data: Uint8Array) => void>> = new Map();

  constructor(baseUrl: string, token: string) {
    this.baseUrl = baseUrl.replace(/\/$/, "");
    this.token = token;
  }

  async listSessions() {
    const res = await fetch(`${this.baseUrl}/api/v1/sessions?token=${encodeURIComponent(this.token)}`);
    if (!res.ok) throw new Error(`Failed to list sessions: ${res.statusText}`);
    const data = await res.json();
    return data.map((s: { sessionId: string }) => ({ sessionId: s.sessionId }));
  }

  async attach(sessionId: string): Promise<TerminalAttachment> {
    const wsProto = this.baseUrl.startsWith("https") ? "wss" : "ws";
    const host = this.baseUrl.replace(/^https?:\/\//, "");
    const wsUrl = `${wsProto}://${host}/api/v1/terminal/${sessionId}?token=${encodeURIComponent(this.token)}`;

    const ws = new WebSocket(wsUrl);
    ws.binaryType = "arraybuffer";

    const listeners = this.outputListeners.get(sessionId) ?? new Set();
    this.outputListeners.set(sessionId, listeners);

    ws.onmessage = (event) => {
      let data: Uint8Array;
      if (typeof event.data === "string") {
        data = new TextEncoder().encode(event.data);
      } else {
        data = new Uint8Array(event.data);
      }
      for (const listener of listeners) {
        listener(data);
      }
    };

    this.sockets.set(sessionId, ws);
    return { sessionId };
  }

  write(sessionId: string, data: string | Uint8Array) {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    const bytes = typeof data === "string" ? new TextEncoder().encode(data) : data;
    ws.send(bytes);
  }

  resize(sessionId: string, cols: number, rows: number) {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: "resize", cols, rows }));
  }

  signal(sessionId: string, signal: "interrupt" | "terminate" | "kill") {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: "signal", signal }));
  }

  async close(sessionId: string) {
    const ws = this.sockets.get(sessionId);
    if (ws) {
      ws.close();
      this.sockets.delete(sessionId);
    }
  }

  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe {
    const listeners = this.outputListeners.get(sessionId) ?? new Set();
    const wrapped = (bytes: Uint8Array) => listener(bytes);
    listeners.add(wrapped);
    this.outputListeners.set(sessionId, listeners);

    return () => {
      listeners.delete(wrapped);
    };
  }

  onLifecycle(_listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe {
    return () => {};
  }
}

