type ProjectBootstrap = {
  projects: RegisteredProject[];
  activeProjectId: string;
};

function loadProjectBootstrap(): ProjectBootstrap {
  return { projects: loadProjects(), activeProjectId: loadActiveProjectId() };
}

function isInitialProjectPlaceholder(project: RegisteredProject, startup: RegisteredProject) {
  return (
    project.workspaceId === DEFAULT_WORKSPACE_ID &&
    (project.repoRoot === "." || project.repoRoot === "" || project.repoRoot === startup.repoRoot)
  );
}

function canonicalizeProjectBootstrap(stored: ProjectBootstrap, startup: RegisteredProject): ProjectBootstrap {
  const replacesPlaceholder = stored.projects.some((project) => isInitialProjectPlaceholder(project, startup));
  if (!replacesPlaceholder) return stored;

  const projects = stored.projects.reduce<RegisteredProject[]>((next, project) => {
    const canonical = isInitialProjectPlaceholder(project, startup) ? startup : project;
    if (!next.some((candidate) => candidate.workspaceId === canonical.workspaceId)) next.push(canonical);
    return next;
  }, []);
  const activeProjectId = stored.activeProjectId === DEFAULT_WORKSPACE_ID ? startup.workspaceId : stored.activeProjectId;
  persistProjects(projects);
  persistActiveProjectId(activeProjectId);
  return { projects, activeProjectId };
}

export function App() {
  const [isNativeRuntime] = useState(() => isTauriRuntime());
  const [bootstrap, setBootstrap] = useState<ProjectBootstrap | null>(() =>
    isNativeRuntime ? null : loadProjectBootstrap(),
  );
  const [bootstrapError, setBootstrapError] = useState<string | null>(null);

  useEffect(() => {
    if (!isNativeRuntime) return;
    let cancelled = false;
    void getInitialProject()
      .then((startup) => {
        if (!cancelled) setBootstrap(canonicalizeProjectBootstrap(loadProjectBootstrap(), startup));
      })
      .catch((error) => {
        if (!cancelled) setBootstrapError(error instanceof Error ? error.message : String(error));
      });
    return () => {
      cancelled = true;
    };
  }, [isNativeRuntime]);

  if (bootstrapError) {
    return (
      <div className="flex h-screen w-screen items-center justify-center bg-background text-xs text-destructive">
        Unable to initialize project: {bootstrapError}
      </div>
    );
  }
  if (!bootstrap) return <div className="h-screen w-screen bg-background" aria-label="Initializing project" />;

  return <WorkspaceApp initialProjects={bootstrap.projects} initialActiveProjectId={bootstrap.activeProjectId} />;
}

function WorkspaceApp({
  initialProjects,
  initialActiveProjectId,
}: {
  initialProjects: RegisteredProject[];
  initialActiveProjectId: string;
}) {
  const [projects, setProjects] = useState<RegisteredProject[]>(initialProjects);
  const [activeProjectId, setActiveProjectId] = useState(initialActiveProjectId);
  const restoredProjectIdRef = useRef<string | null>(null);
  const activeProject = useMemo(
    () => projects.find((project) => project.workspaceId === activeProjectId) ?? projects[0] ?? DEFAULT_PROJECT,
    [activeProjectId, projects],
  );

  const projectsRef = useRef(projects);
  projectsRef.current = projects;
  const activeProjectRef = useRef(activeProject);
  activeProjectRef.current = activeProject;

  const [agentSettings, setAgentSettings] = useState<AgentSettings>(loadAgentSettings);
  const [agentDetections, setAgentDetections] = useState<AgentDetection[]>([]);

  useEffect(() => {
    let cancelled = false;
    async function runDetection() {
      if (!isTauriRuntime()) return;
      try {
        const results = await detectAgents([...AGENT_CANDIDATES]);
        if (!cancelled) setAgentDetections(results);
      } catch (error) {
        console.warn("Failed to detect agents:", error);
      }
    }
    void runDetection();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    const handleSettingsChange = () => {
      setAgentSettings(loadAgentSettings());
    };
    window.addEventListener(AGENTS_SETTINGS_CHANGED_EVENT, handleSettingsChange);
    return () => window.removeEventListener(AGENTS_SETTINGS_CHANGED_EVENT, handleSettingsChange);
  }, []);

  const resolvedAgents = useMemo(
    () => mergeDetections(agentSettings, agentDetections),
    [agentSettings, agentDetections],
  );

  const launchableAgents = useMemo(
    () => getLaunchableAgents(resolvedAgents),
    [resolvedAgents],
  );

  const {
    state,
    recoveredFromHmr,
    agents,
    tabActivity,
    worktreeActivity,
    updateSessionTitleActivity,
    openTab,
    createBrowserTab,
    navigateBrowserTab,
    reloadBrowserTab,
    ensureTabForWorktree,
    closeTab,
    closeOtherTabs,
    closeTabsToRight,
    closeTabsToLeft,
    splitPane,
    moveTabToGroup,
    moveTabToSplit,
    detachPaneToTab,
    closePane,
    activateTab,
    reorderTab,
    renameTab,
    setTabPinned,
    focusPane,
    setPaneRatio,
    setTabGroupRatio,
    swapPanes,
    syncWorktrees,
    restoreWorkspace,
  } = useWorkspaceStore({ workspaceId: activeProject.workspaceId });
  const stateRef = useRef(state);
  stateRef.current = state;
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    workspaceId: activeProject.workspaceId,
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });

  useEffect(() => {
    void registerProject({
      workspaceId: activeProject.workspaceId,
      repoPath: activeProject.repoRoot,
    })
      .then(() => refreshWorktrees())
      .catch(reportRuntimeError);
  }, [activeProject.repoRoot, activeProject.workspaceId, refreshWorktrees, reportRuntimeError]);

  // Initial session restore on startup & HMR recovery.
  useEffect(() => {
    if (restoredProjectIdRef.current === activeProject.workspaceId) return;
    restoredProjectIdRef.current = activeProject.workspaceId;
    if (recoveredFromHmr) return;
    let cancelled = false;
    async function restore() {
      try {
        const session = await loadSession();
        if (cancelled || !session) return;

        const liveSessions = await defaultTauriTransport.listSessions().catch(() => []);
        const liveBackendIds = new Set(liveSessions.map((candidate) => candidate.sessionId));
        const restoredState = deserializeWorkspaceState(activeProject.workspaceId, session, liveBackendIds);

        const hasRestoredTabs =
          restoredState &&
          (restoredState.layout.tabs.length > 0 ||
            Object.values(restoredState.worktreeLayouts ?? {}).some((l) => l.tabs.length > 0));

        if (hasRestoredTabs) {
          restoreWorkspace(restoredState);

          // A persisted local session can outlive its native PTY. Respawn only the dead
          // native side while preserving the local session/leaf ownership graph.
          const deadSessions = Object.values(restoredState.sessions).filter((candidate) => !candidate.backendSessionId);
          if (deadSessions.length > 0) {
            let hasSpawned = false;
            await ensureTerminalEvents().catch(() => undefined);
            for (const restoredSession of deadSessions) {
              if (cancelled) return;
              try {
                const worktreePath = restoredSession.worktreePath ?? restoredSession.cwd;
                const foundWorktree = restoredState.worktrees.find((worktree) => worktree.path === worktreePath);
                const backendSessionId = await spawnTerminal({
                  workspaceId: activeProject.workspaceId,
                  worktree: foundWorktree ? worktreeIdentity(foundWorktree) : null,
                  cwd: restoredSession.cwd,
                });
                restoredSession.backendSessionId = backendSessionId;
                restoredSession.lifecycle = "working";
                hasSpawned = true;
              } catch (error) {
                console.warn("Failed to respawn terminal session on restore:", error);
              }
            }

            if (hasSpawned && !cancelled) restoreWorkspace({ ...restoredState });
          }
          // Typed v2 restoration already reconstructed every tab. Do not run the legacy
          // per-worktree fallback as well or it can create duplicate terminal tabs.
          return;
        }

        // Legacy best-effort fallback for sessions that cannot be deserialized as a
        // workspace state. Browser records are skipped because they require explicit v2
        // browser metadata and should never be guessed from terminal fields.
        const workspace = session.workspaces?.[activeProject.workspaceId];
        if (!workspace || !workspace.layout?.tabs?.length) return;
        for (const persistedTab of workspace.layout.tabs) {
          if (cancelled) return;
          if (persistedTab.kind === "browser") continue;
          const legacyWorktreePath = persistedTab.worktreePath || workspace.repoRoot;
          const found = workspace.worktrees?.find((candidate) => candidate.path === legacyWorktreePath);
          const worktree: Worktree = found
            ? {
                path: found.path,
                head: found.head,
                branch: found.branch,
                bare: false,
                detached: false,
                locked: found.isLocked ? "locked" : null,
                prunable: null,
              }
            : {
                path: legacyWorktreePath,
                head: "",
                branch: persistedTab.label,
                bare: false,
                detached: false,
                locked: null,
                prunable: null,
              };
          try {
            const alreadyOpen = state.layout.tabs.some((tab) => {
              if (tab.kind === "browser") return false;
              const localSession = state.sessions[tab.sessionId];
              return (localSession?.worktreePath ?? localSession?.cwd) === worktree.path;
            });
            if (!alreadyOpen) await ensureTabForWorktree(worktree);
          } catch {
            // Safe fallback if the terminal for this worktree is already open.
          }
        }
      } catch (error) {
        console.warn("Session restore on boot skipped:", error);
      }
    }
    void restore();
    return () => {
      cancelled = true;
    };
  }, [activeProject.workspaceId, ensureTabForWorktree, restoreWorkspace]);

  const saveChainRef = useRef<Promise<void>>(Promise.resolve());
  const persistSession = useCallback((workspaceId: string, repoRoot: string, currentState: WorkspaceState) => {
    saveChainRef.current = saveChainRef.current
      .then(async () => {
        const existing = await loadSession().catch(() => null);
        const session = serializeWorkspaceState(
          workspaceId,
          repoRoot,
          currentState,
          existing,
        );
        await saveSession(session);
      })
      .catch((error) => {
        console.error("Failed to save workspace session:", error);
      });
    return saveChainRef.current;
  }, []);

  useEffect(() => {
    const unregister = registerWindowCloseGuard(async () => {
      await persistSession(activeProjectRef.current.workspaceId, activeProjectRef.current.repoRoot, stateRef.current);
    });
    return unregister;
  }, [persistSession]);

  useEffect(() => {
    const hasTabs =
      state.layout.tabs.length > 0 ||
      Object.values(state.worktreeLayouts ?? {}).some((l) => l.tabs.length > 0);
    if (state.worktrees.length === 0 || !hasTabs) return;
    const timer = setTimeout(() => {
      void persistSession(activeProject.workspaceId, activeProject.repoRoot, stateRef.current);
    }, 500);
    return () => clearTimeout(timer);
  }, [activeProject.repoRoot, activeProject.workspaceId, persistSession, state]);

  const [isAddProjectOpen, setIsAddProjectOpen] = useState(false);
  const [createTargetProject, setCreateTargetProject] = useState<RegisteredProject | null>(null);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [searchLeafId, setSearchLeafId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(loadSidebarOpen);
  const [deleteTarget, setDeleteTarget] = useState<Worktree | null>(null);
  const [worktreeStatuses, setWorktreeStatuses] = useState<Record<string, DirtyState | undefined>>({});
  const [pendingWorktreePath, setPendingWorktreePath] = useState<string | null>(null);

  const toggleSidebar = useCallback(() => {
    setIsSidebarOpen((current) => {
      const next = !current;
      persistSidebarOpen(next);
      return next;
    });
  }, []);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );
  const activeWorktreeRef = useRef(activeWorktree);
  activeWorktreeRef.current = activeWorktree;

  const handleSelectProject = useCallback(
    (project: RegisteredProject) => {
      if (project.workspaceId === activeProjectRef.current.workspaceId) return;
      setActiveProjectId(project.workspaceId);
      persistActiveProjectId(project.workspaceId);
      setWorktreeStatuses({});
      setDeleteTarget(null);
      setPendingWorktreePath(null);
    },
    [],
  );

  const handleRegisteredProject = useCallback((project: RegisteredProject) => {
    setProjects((current) => {
      const next = [...current.filter((candidate) => candidate.workspaceId !== project.workspaceId), project];
      persistProjects(next);
      return next;
    });
    setActiveProjectId(project.workspaceId);
    persistActiveProjectId(project.workspaceId);
    setWorktreeStatuses({});
  }, []);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      const ownerId = worktreeIdentity(worktree)?.wsId;
      const owner = ownerId ? projectsRef.current.find((project) => project.workspaceId === ownerId) : undefined;
      if (owner && owner.workspaceId !== activeProjectRef.current.workspaceId) {
        handleSelectProject(owner);
        setPendingWorktreePath(worktree.path);
        return;
      }
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [ensureTabForWorktree, handleSelectProject, reportRuntimeError],
  );

  useEffect(() => {
    if (!pendingWorktreePath) return;
    const target = state.worktrees.find((worktree) => worktree.path === pendingWorktreePath);
    if (!target) return;
    setPendingWorktreePath(null);
    void ensureTabForWorktree(target).catch(reportRuntimeError);
  }, [ensureTabForWorktree, pendingWorktreePath, reportRuntimeError, state.worktrees]);

  const handleSelectTerminalTab = useCallback(
    (tabId: string) => {
      const currentState = stateRef.current;
      const tab = currentState.layout.tabs.find((candidate) => candidate.id === tabId);
      if (!tab) return;
      if (tab.kind === "browser") {
        activateTab(tabId);
        return;
      }
      const session = currentState.sessions[tab.sessionId];
      const sessionWorktreePath = session?.worktreePath ?? session?.cwd;
      const worktree = sessionWorktreePath
        ? currentState.worktrees.find((candidate) => candidate.path === sessionWorktreePath)
        : undefined;
      if (!worktree || worktree.path === currentState.activeWorktreePath) {
        activateTab(tabId);
        return;
      }
      void ensureTabForWorktree(worktree)
        .then(() => activateTab(tabId))
        .catch(reportRuntimeError);
    },
    [activateTab, ensureTabForWorktree, reportRuntimeError],
  );

  const handleAddTerminalTab = useCallback(() => {
    const activeWt = activeWorktreeRef.current;
    if (!activeWt) return;
    void openTab(activeWt).catch(reportRuntimeError);
  }, [openTab, reportRuntimeError]);

  const handleLaunchAgent = useCallback(
    async (agent: { name: string; command: string; args: string }) => {
      try {
        const targetWorktree = activeWorktreeRef.current ?? stateRef.current.worktrees[0];
        if (!targetWorktree) return;
        await ensureTerminalEvents().catch(() => undefined);
        const backendSessionId = await spawnTerminal({
          workspaceId: activeProjectRef.current.workspaceId,
          worktree: worktreeIdentity(targetWorktree),
          cwd: targetWorktree.path,
        });
        const label = agent.name.charAt(0).toUpperCase() + agent.name.slice(1);
        await openTab(targetWorktree, label, backendSessionId);
        const fullCommand = `${agent.command} ${agent.args}`.trim();
        if (fullCommand) {
          await writeTerminal({ sessionId: backendSessionId, data: `${fullCommand}\r` });
        }
      } catch (error) {
        reportRuntimeError(error);
      }
    },
    [openTab, reportRuntimeError],
  );

  useEffect(() => {
    let unlisten: (() => void) | null = null;
    let cancelled = false;
    void onNewTerminalTabMenu(handleAddTerminalTab).then((dispose) => {
      if (cancelled) dispose();
      else unlisten = dispose;
    });
    return () => {
      cancelled = true;
      unlisten?.();
    };
  }, [handleAddTerminalTab]);

  const handleCloseTab = useCallback(
    (tabId: string) => {
      void closeTab(tabId).catch(reportRuntimeError);
    },
    [closeTab, reportRuntimeError],
  );

  const handleCloseOtherTabs = useCallback(
    (tabId: string) => {
      void closeOtherTabs(tabId).catch(reportRuntimeError);
    },
    [closeOtherTabs, reportRuntimeError],
  );

  const handleCloseTabsToRight = useCallback(
    (tabId: string) => {
      void closeTabsToRight(tabId).catch(reportRuntimeError);
    },
    [closeTabsToRight, reportRuntimeError],
  );

  const handleCloseTabsToLeft = useCallback(
    (tabId: string) => {
      void closeTabsToLeft(tabId).catch(reportRuntimeError);
    },
    [closeTabsToLeft, reportRuntimeError],
  );

  const handleCycleTab = useCallback(
    (offset: number) => {
      const currentState = stateRef.current;
      const focusedGroup = currentState.layout.focusedGroupId
        ? currentState.layout.tabGroups?.[currentState.layout.focusedGroupId]
        : undefined;
      const tabById = new Map(currentState.layout.tabs.map((tab) => [tab.id, tab]));
      const tabs: WorkspaceTab[] = focusedGroup
        ? focusedGroup.tabIds.map((tabId) => tabById.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab))
        : currentState.layout.tabs;
      if (tabs.length < 2) return;
      const currentIndex = Math.max(0, tabs.findIndex((tab) => tab.id === currentState.layout.activeTabId));
      const nextIndex = (currentIndex + offset + tabs.length) % tabs.length;
      handleSelectTerminalTab(tabs[nextIndex].id);
    },
    [handleSelectTerminalTab],
  );

  const handleSplitActive = useCallback(
    (direction: PaneDirection) => {
      const currentState = stateRef.current;
      const activeTab = currentState.layout.tabs.find((tab) => tab.id === currentState.layout.activeTabId) ?? currentState.layout.tabs[0];
      if (!activeTab || activeTab.kind === "browser") return;
      const activeLayout = currentState.layout.layoutsByTabId?.[activeTab.id];
      const targetLeafId = activeLayout?.activeLeafId ?? "leaf-default";
      void splitPane(activeTab.id, targetLeafId, direction).catch(reportRuntimeError);
    },
    [reportRuntimeError, splitPane],
  );

  const handleUnsplitActive = useCallback(() => {
    const currentState = stateRef.current;
    const activeTab = currentState.layout.tabs.find((tab) => tab.id === currentState.layout.activeTabId) ?? currentState.layout.tabs[0];
    if (!activeTab || activeTab.kind === "browser") return;
    const activeLayout = currentState.layout.layoutsByTabId?.[activeTab.id];
    if (!activeLayout || activeLayout.root.type === "leaf") return;
    const activeLeafId = activeLayout.activeLeafId ?? "leaf-default";
    void closePane(activeTab.id, activeLeafId).catch(reportRuntimeError);
  }, [closePane, reportRuntimeError]);

  const handleCyclePaneFocus = useCallback(
    (offset: number) => {
      const currentState = stateRef.current;
      const activeTab = currentState.layout.tabs.find((tab) => tab.id === currentState.layout.activeTabId) ?? currentState.layout.tabs[0];
      if (!activeTab || activeTab.kind === "browser") return;
      const activeLayout = currentState.layout.layoutsByTabId?.[activeTab.id];
      if (!activeLayout) return;
      const leafIds = collectLeafIds(activeLayout.root);
      if (leafIds.length < 2) return;
      const activeLeafId = activeLayout.activeLeafId ?? leafIds[0];
      const currentIndex = Math.max(0, leafIds.indexOf(activeLeafId));
      const nextIndex = (currentIndex + offset + leafIds.length) % leafIds.length;
      focusPane(activeTab.id, leafIds[nextIndex]);
    },
    [focusPane],
  );

  const handleOpenTerminalSearch = useCallback(() => {
    const currentState = stateRef.current;
    const activeTab = currentState.layout.tabs.find((tab) => tab.id === currentState.layout.activeTabId) ?? currentState.layout.tabs[0];
    if (!activeTab || activeTab.kind === "browser") return;
    const activeLayout = currentState.layout.layoutsByTabId?.[activeTab.id];
    const leafId = activeLayout?.activeLeafId ?? (activeLayout?.root ? collectLeafIds(activeLayout.root)[0] : "leaf-default");
    setSearchLeafId(leafId);
  }, []);

  const handleSelectWorktreeByIndex = useCallback(
    (index: number) => {
      const visible = listVisibleWorktrees(projectsRef.current, stateRef.current.worktrees, activeProjectRef.current.workspaceId);
      const target = visible[index];
      if (target) handleSelectWorktree(target);
    },
    [handleSelectWorktree],
  );

  const { settings: terminalSettings, updateSettings: updateTerminalSettings } = useTerminalSettings();
  const terminalSettingsRef = useRef(terminalSettings);
  terminalSettingsRef.current = terminalSettings;

  const handleZoomIn = useCallback(() => {
    const nextSize = Math.min(36, terminalSettingsRef.current.fontSize + 1);
    updateTerminalSettings({ fontSize: nextSize });
  }, [updateTerminalSettings]);

  const handleZoomOut = useCallback(() => {
    const nextSize = Math.max(10, terminalSettingsRef.current.fontSize - 1);
    updateTerminalSettings({ fontSize: nextSize });
  }, [updateTerminalSettings]);

  const handleZoomReset = useCallback(() => {
    updateTerminalSettings({ fontSize: null });
  }, [updateTerminalSettings]);

  const handleSelectTerminalTabByIndex = useCallback(
    (index: number) => {
      const currentState = stateRef.current;
      const focusedGroup = currentState.layout.focusedGroupId
        ? currentState.layout.tabGroups?.[currentState.layout.focusedGroupId]
        : undefined;
      const tabId = focusedGroup?.tabIds[index] ?? currentState.layout.tabs[index]?.id;
      if (tabId) handleSelectTerminalTab(tabId);
    },
    [handleSelectTerminalTab],
  );

  const handleOpenAddProject = useCallback(() => setIsAddProjectOpen(true), []);
  const handleCloseAddProject = useCallback(() => setIsAddProjectOpen(false), []);
  const handleOpenCreateWorktree = useCallback((project?: RegisteredProject) => {
    setCreateTargetProject(project ?? activeProjectRef.current);
    setIsCreateOpen(true);
  }, []);
  const handleCloseCreateWorktree = useCallback(() => {
    setIsCreateOpen(false);
    setCreateTargetProject(null);
  }, []);
  const handleOpenCommandPalette = useCallback(() => setIsCommandPaletteOpen(true), []);
  const handleCloseCommandPalette = useCallback(() => setIsCommandPaletteOpen(false), []);
  const handleOpenSettings = useCallback(() => setIsSettingsOpen(true), []);
  const handleCloseSettings = useCallback(() => setIsSettingsOpen(false), []);
  const handleToggleSettings = useCallback(() => setIsSettingsOpen((current) => !current), []);
  const handleCloseSearch = useCallback(() => setSearchLeafId(null), []);
  const handleCloseDeleteTarget = useCallback(() => setDeleteTarget(null), []);

  const handleAddBrowserTab = useCallback(
    (url?: string) => {
      void createBrowserTab(url ?? newBrowserTabUrl()).catch(reportRuntimeError);
    },
    [createBrowserTab, reportRuntimeError],
  );

  const handleNavigateBrowserTab = useCallback(
    (tabId: string, url: string) => {
      void navigateBrowserTab(tabId, url).catch(reportRuntimeError);
    },
    [navigateBrowserTab, reportRuntimeError],
  );

  const handleReloadBrowserTab = useCallback(
    (tabId: string) => {
      void reloadBrowserTab(tabId).catch(reportRuntimeError);
    },
    [reloadBrowserTab, reportRuntimeError],
  );

  const handleSplitPane = useCallback(
    (tabId: string, leafId: string, direction: PaneDirection, options?: { position?: "first" | "second" }) => {
      void splitPane(tabId, leafId, direction, options).catch(reportRuntimeError);
    },
    [reportRuntimeError, splitPane],
  );

  const handleClosePane = useCallback(
    (tabId: string, leafId: string) => {
      void closePane(tabId, leafId).catch(reportRuntimeError);
    },
    [closePane, reportRuntimeError],
  );

  const shortcutHandlers = useMemo(
    () => ({
      "tab.newTerminal": handleAddTerminalTab,
      "tab.newBrowser": () => void createBrowserTab(newBrowserTabUrl()).catch(reportRuntimeError),
      "tab.close": () => {
        const activeTabId = stateRef.current.layout.activeTabId;
        if (activeTabId) handleCloseTab(activeTabId);
      },
      "tab.next": () => handleCycleTab(1),
      "tab.previous": () => handleCycleTab(-1),
      "tab.select1": () => handleSelectTerminalTabByIndex(0),
      "tab.select2": () => handleSelectTerminalTabByIndex(1),
      "tab.select3": () => handleSelectTerminalTabByIndex(2),
      "tab.select4": () => handleSelectTerminalTabByIndex(3),
      "tab.select5": () => handleSelectTerminalTabByIndex(4),
      "tab.select6": () => handleSelectTerminalTabByIndex(5),
      "tab.select7": () => handleSelectTerminalTabByIndex(6),
      "tab.select8": () => handleSelectTerminalTabByIndex(7),
      "tab.select9": () => handleSelectTerminalTabByIndex(8),
      "workspace.select1": () => handleSelectWorktreeByIndex(0),
      "workspace.select2": () => handleSelectWorktreeByIndex(1),
      "workspace.select3": () => handleSelectWorktreeByIndex(2),
      "workspace.select4": () => handleSelectWorktreeByIndex(3),
      "workspace.select5": () => handleSelectWorktreeByIndex(4),
      "workspace.select6": () => handleSelectWorktreeByIndex(5),
      "workspace.select7": () => handleSelectWorktreeByIndex(6),
      "workspace.select8": () => handleSelectWorktreeByIndex(7),
      "workspace.select9": () => handleSelectWorktreeByIndex(8),
      "terminal.splitRight": () => handleSplitActive("horizontal"),
      "terminal.splitDown": () => handleSplitActive("vertical"),
      "terminal.unsplit": handleUnsplitActive,
      "terminal.focusNext": () => handleCyclePaneFocus(1),
      "terminal.focusPrevious": () => handleCyclePaneFocus(-1),
      "terminal.search": handleOpenTerminalSearch,
      "sidebar.left.toggle": toggleSidebar,
      "commandPalette.open": handleOpenCommandPalette,
      "settings.toggle": handleToggleSettings,
      "zoom.in": handleZoomIn,
      "zoom.out": handleZoomOut,
      "zoom.reset": handleZoomReset,
    }),
    [
      createBrowserTab,
      handleAddTerminalTab,
      handleCloseTab,
      handleCyclePaneFocus,
      handleCycleTab,
      handleOpenCommandPalette,
      handleOpenTerminalSearch,
      handleSelectTerminalTabByIndex,
      handleSelectWorktreeByIndex,
      handleSplitActive,
      handleToggleSettings,
      handleUnsplitActive,
      handleZoomIn,
      handleZoomOut,
      handleZoomReset,
      reportRuntimeError,
      toggleSidebar,
    ],
  );
  useShortcuts(shortcutHandlers);

  return (
    <div className="flex h-screen w-screen select-none overflow-hidden bg-background font-sans text-foreground">
      {isSidebarOpen ? (
        <Sidebar
          open={true}
          projects={projects}
          activeProjectId={activeProject.workspaceId}
          worktrees={state.worktrees}
          agents={agents}
          activePath={activeWorktree?.path || ""}
          statuses={worktreeStatuses}
          unreadWorktreePaths={state.unreadWorktreePaths}
          activityByWorktreePath={worktreeActivity}
          onSelectProject={handleSelectProject}
          onAddProject={handleOpenAddProject}
          onSelectWorktree={handleSelectWorktree}
          onCreateWorktree={handleOpenCreateWorktree}
          onDeleteWorktree={setDeleteTarget}
          onOpenSettings={handleOpenSettings}
          onToggle={toggleSidebar}
        />
      ) : (
        <div className="relative w-0 shrink-0 overflow-visible">
          <div className="titlebar-left-floating absolute top-0 left-0 z-20 flex h-titlebar shrink-0 items-center border-b border-r border-border bg-card px-2">
            {isMacShortcutPlatform() ? (
              <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" />
            ) : null}
            <IconButton label="Show sidebar" className="no-drag" size="sm" onClick={toggleSidebar}>
              <PanelLeft className="size-3.5" />
            </IconButton>
          </div>
        </div>
      )}

      <main className="flex h-full min-w-0 flex-1 flex-col overflow-hidden bg-background">
        {activeWorktree ? (
          <TerminalSplitView
            layout={state.layout}
            sessions={state.sessions}
            unreadTabIds={state.unreadTabIds}
            activityByTabId={tabActivity}
            onTitleChange={updateSessionTitleActivity}
            onActivateTab={handleSelectTerminalTab}
            onCloseTab={handleCloseTab}
            onCloseOtherTabs={handleCloseOtherTabs}
            onCloseTabsToRight={handleCloseTabsToRight}
            onCloseTabsToLeft={handleCloseTabsToLeft}
            onReorderTab={reorderTab}
            onMoveTabToGroup={moveTabToGroup}
            onMoveTabToSplit={moveTabToSplit}
            onDetachPaneToTab={detachPaneToTab}
            onRenameTab={renameTab}
            onToggleTabPin={setTabPinned}
            onAddTab={handleAddTerminalTab}
            onAddBrowserTab={handleAddBrowserTab}
            onOpenSettings={handleOpenSettings}
            agents={launchableAgents}
            onLaunchAgent={handleLaunchAgent}
            defaultAgentId={agentSettings.defaultAgentId}
            onNavigateBrowserTab={handleNavigateBrowserTab}
            onReloadBrowserTab={handleReloadBrowserTab}
            onSplitPane={handleSplitPane}
            onClosePane={handleClosePane}
            onSetRatio={setPaneRatio}
            onSetGroupRatio={setTabGroupRatio}
            onSwapPanes={swapPanes}
            onFocusPane={focusPane}
            searchLeafId={searchLeafId}
            onCloseSearch={handleCloseSearch}
            leadingSpacer={isSidebarOpen ? 0 : isMacShortcutPlatform() ? 108 : 36}
          />
        ) : (
          <div className="flex h-full flex-1 items-center justify-center bg-background text-xs text-muted-foreground">
            {runtimeError ? `Workspace unavailable (${runtimeError.code})` : "No workspace available"}
          </div>
        )}
      </main>

      {isCommandPaletteOpen ? (
        <CommandPalette
          open={true}
          worktrees={state.worktrees}
          tabs={state.layout.tabs}
          onSelectWorktree={handleSelectWorktree}
          onSelectTab={handleSelectTerminalTab}
          onClose={handleCloseCommandPalette}
        />
      ) : null}
      {isSettingsOpen ? (
        <Suspense fallback={null}>
          <SettingsDialog
            open
            onClose={handleCloseSettings}
            projects={projects}
            activeProjectId={activeProject.workspaceId}
            activeWorktree={activeWorktree}
            onSelectProject={handleSelectProject}
            onAddProject={handleOpenAddProject}
            onAddWorktree={handleOpenCreateWorktree}
          />
        </Suspense>
      ) : null}
      {isAddProjectOpen ? (
        <AddProjectDialog
          projects={projects}
          onClose={handleCloseAddProject}
          onRegistered={handleRegisteredProject}
        />
      ) : null}
      {isCreateOpen ? (
        <AddWorktreeDialog
          project={createTargetProject ?? activeProject}
          onClose={handleCloseCreateWorktree}
          onCreated={async (worktree) => {
            const owner = createTargetProject ?? activeProject;
            if (owner.workspaceId !== activeProject.workspaceId) {
              handleSelectProject(owner);
              setPendingWorktreePath(worktree.path);
              return;
            }
            await refreshWorktrees();
            await ensureTabForWorktree(worktree).catch(reportRuntimeError);
          }}
        />
      ) : null}
      {deleteTarget ? (
        <WorktreeDeleteDialog
          workspaceId={activeProject.workspaceId}
          worktree={deleteTarget}
          onClose={handleCloseDeleteTarget}
          onDeleted={() => {
            setWorktreeStatuses((current) => {
              const next = { ...current };
              delete next[deleteTarget.path];
              return next;
            });
            void refreshWorktrees();
          }}
        />
      ) : null}

      {runtimeError && activeWorktree ? (
        <div className="pointer-events-none fixed bottom-3 right-3 z-40 max-w-error border border-destructive/30 bg-card/95 px-3 py-2 text-[11px] text-destructive shadow-lg">
          {runtimeError.code}: {runtimeError.message}
        </div>
      ) : null}
    </div>
  );
}

function listVisibleWorktrees(
  projects: RegisteredProject[],
  worktrees: Worktree[],
  activeProjectId: string,
): Worktree[] {
  const collapsed = loadCollapsedProjectIds(projects, activeProjectId);
  const known = new Set(projects.map((project) => project.workspaceId));
  const visible: Worktree[] = [];

  for (const project of projects) {
    if (collapsed.has(project.workspaceId)) continue;
    for (const worktree of worktrees) {
      const ownerId = worktreeIdentity(worktree)?.wsId;
      const owner = ownerId && known.has(ownerId) ? ownerId : activeProjectId;
      if (owner === project.workspaceId) visible.push(worktree);
    }
  }

  return visible;
}

function loadCollapsedProjectIds(projects: RegisteredProject[], activeProjectId: string): Set<string> {
  try {
    const raw = getMigratedItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY);
    const parsed: unknown = raw ? JSON.parse(raw) : null;
    if (Array.isArray(parsed)) return new Set(parsed.filter((id): id is string => typeof id === "string"));
    return new Set(projects.filter((project) => project.workspaceId !== activeProjectId).map((project) => project.workspaceId));
  } catch {
    return new Set<string>();
  }
}

function loadProjects(): RegisteredProject[] {
  try {
    const raw = getMigratedItem(PROJECTS_STORAGE_KEY);
    if (!raw) return [DEFAULT_PROJECT];
    const parsed = JSON.parse(raw) as RegisteredProject[];
    if (!Array.isArray(parsed)) return [DEFAULT_PROJECT];
    const valid = parsed.filter(
      (project) => project && typeof project.workspaceId === "string" && typeof project.repoRoot === "string",
    );
    return valid.length > 0 ? valid : [DEFAULT_PROJECT];
  } catch {
    return [DEFAULT_PROJECT];
  }
}

function persistProjects(projects: RegisteredProject[]) {
  try {
    window.localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify(projects));
  } catch {
    // A local persistence failure must not block native project registration.
  }
}

function loadActiveProjectId() {
  try {
    return getMigratedItem(ACTIVE_PROJECT_STORAGE_KEY) || DEFAULT_WORKSPACE_ID;
  } catch {
    return DEFAULT_WORKSPACE_ID;
  }
}

function persistActiveProjectId(workspaceId: string) {
  try {
    window.localStorage.setItem(ACTIVE_PROJECT_STORAGE_KEY, workspaceId);
  } catch {
    // The selected project still remains active for this session.
  }
}

function loadSidebarOpen() {
  try {
    const raw = getMigratedItem(SIDEBAR_OPEN_STORAGE_KEY);
    return raw !== null ? raw !== "false" : true;
  } catch {
    return true;
  }
}

function persistSidebarOpen(open: boolean) {
  try {
    window.localStorage.setItem(SIDEBAR_OPEN_STORAGE_KEY, String(open));
  } catch {
    // Persistence failure should not break in-memory state.
  }
}

export default App;

import {
  createTerminalInstance,
  disposeTerminalInstance,
  type TerminalInstance,
} from "./terminalInstanceFactory";
import { attachScheduledOutputSubscription, MAX_PENDING_OUTPUT_CHARS } from "./terminalOutputScheduler";
import {
  applyTerminalSettings,
  type EffectiveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type { TerminalInstance };
export { MAX_PENDING_OUTPUT_CHARS };

export const DEFAULT_WARM_CACHE_LIMIT = 2;

type SpawnGeneration = {
  generation: number;
  activeCount: number;
};

class TerminalHostManager {
  private instances = new Map<string, TerminalInstance>();
  private pendingSpawns = new Map<string, Promise<TerminalInstance>>();
  private spawnGenerations = new Map<string, SpawnGeneration>();
  private visibleRefCounts = new Map<string, number>();
  private inactiveLruSessionIds: string[] = [];
  private warmCacheLimit = DEFAULT_WARM_CACHE_LIMIT;

  setWarmCacheLimit(limit: number): void {
    this.warmCacheLimit = Math.max(0, limit);
    this.evictInactiveIfNeeded();
  }

  getWarmCacheLimit(): number {
    return this.warmCacheLimit;
  }

  isSessionVisible(sessionId: string): boolean {
    return (this.visibleRefCounts.get(sessionId) ?? 0) > 0;
  }

  registerVisible(sessionId: string): () => void {
    const current = this.visibleRefCounts.get(sessionId) ?? 0;
    this.visibleRefCounts.set(sessionId, current + 1);
    if (current === 0) {
      this.markSessionVisible(sessionId);
    }
    let unregistered = false;
    return () => {
      if (unregistered) return;
      unregistered = true;
      const count = (this.visibleRefCounts.get(sessionId) ?? 1) - 1;
      if (count <= 0) {
        this.visibleRefCounts.delete(sessionId);
        this.markSessionInactive(sessionId);
      } else {
        this.visibleRefCounts.set(sessionId, count);
      }
    };
  }

  setVisible(sessionId: string, visible: boolean): void {
    if (visible) {
      const current = this.visibleRefCounts.get(sessionId) ?? 0;
      this.visibleRefCounts.set(sessionId, Math.max(1, current));
      this.markSessionVisible(sessionId);
    } else {
      this.visibleRefCounts.delete(sessionId);
      this.markSessionInactive(sessionId);
    }
  }

  private markSessionVisible(sessionId: string): void {
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    const inst = this.instances.get(sessionId);
    if (inst) {
      if (!inst.unsubscribeOutput) {
        inst.terminal.reset();
        if (inst.session.backendSessionId) {
          inst.unsubscribeOutput = attachScheduledOutputSubscription(inst.session.backendSessionId, inst.terminal);
        }
      }
    }
  }

  private markSessionInactive(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      inst.unsubscribeOutput?.();
      inst.unsubscribeOutput = undefined;
    }
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.inactiveLruSessionIds.push(sessionId);
    this.evictInactiveIfNeeded();
  }

  private evictInactiveIfNeeded(): void {
    while (this.inactiveLruSessionIds.length > this.warmCacheLimit) {
      const oldestSessionId = this.inactiveLruSessionIds.shift();
      if (!oldestSessionId) break;
      this.disposeFrontendInstance(oldestSessionId);
    }
  }

  private disposeFrontendInstance(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      this.instances.delete(sessionId);
      disposeTerminalInstance(inst);
    }
  }

  getInstance(sessionId: string): TerminalInstance | undefined {
    return this.instances.get(sessionId);
  }

  async getOrCreate(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const isVisible = this.isSessionVisible(session.id);
    const existing = this.instances.get(session.id);
    if (existing) {
      existing.session = session;
      existing.active = active;
      existing.onBell = onBell;
      existing.onTitleChange = onTitleChange;

      if (isVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!existing.unsubscribeOutput) {
          existing.terminal.reset();
          if (session.backendSessionId) {
            existing.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, existing.terminal);
          }
        }
      } else {
        if (existing.unsubscribeOutput) {
          existing.unsubscribeOutput();
          existing.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return existing;
    }

    const pending = this.pendingSpawns.get(session.id);
    if (pending) return pending;

    const currentGen = this.spawnGenerations.get(session.id);
    const generation = (currentGen ? currentGen.generation : 0) + 1;
    const activeCount = (currentGen ? currentGen.activeCount : 0) + 1;
    this.spawnGenerations.set(session.id, { generation, activeCount });

    const spawnPromise = createTerminalInstance({
      session,
      active,
      isVisible: this.isSessionVisible(session.id),
      onBell,
      onTitleChange,
      getInstance: (id) => this.instances.get(id),
    });
    this.pendingSpawns.set(session.id, spawnPromise);

    try {
      const instance = await spawnPromise;
      if (this.spawnGenerations.get(session.id)?.generation !== generation) {
        disposeTerminalInstance(instance);
        return instance;
      }

      this.instances.set(session.id, instance);

      const stillVisible = this.isSessionVisible(session.id);
      if (stillVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!instance.unsubscribeOutput && session.backendSessionId) {
          instance.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, instance.terminal);
        }
      } else {
        if (instance.unsubscribeOutput) {
          instance.unsubscribeOutput();
          instance.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return instance;
    } finally {
      const tracking = this.spawnGenerations.get(session.id);
      if (tracking) {
        tracking.activeCount -= 1;
        if (tracking.activeCount <= 0) {
          this.spawnGenerations.delete(session.id);
        }
      }
      if (this.pendingSpawns.get(session.id) === spawnPromise) {
        this.pendingSpawns.delete(session.id);
      }
    }
  }

  updateSession(sessionId: string, session: TerminalSession) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      const prevBackendId = inst.session.backendSessionId;
      inst.session = session;
      const isVisible = this.isSessionVisible(sessionId);
      if (isVisible) {
        if (session.backendSessionId !== prevBackendId) {
          inst.unsubscribeOutput?.();
          inst.unsubscribeOutput = undefined;
          if (session.backendSessionId) {
            inst.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, inst.terminal);
          }
        }
      } else {
        if (inst.unsubscribeOutput) {
          inst.unsubscribeOutput();
          inst.unsubscribeOutput = undefined;
        }
      }
    }
  }

  applyInstanceSettings(sessionId: string, settings: EffectiveTerminalSettings) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  destroy(sessionId: string) {
    const tracking = this.spawnGenerations.get(sessionId);
    if (tracking) {
      tracking.generation += 1;
    }
    this.visibleRefCounts.delete(sessionId);
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.pendingSpawns.delete(sessionId);
    this.disposeFrontendInstance(sessionId);
  }
}

export const terminalHostManager = new TerminalHostManager();

import type { TerminalLifecyclePayload, TerminalOutputPayload } from "./types";
import { onTerminalLifecycle, onTerminalOutput } from "./tauri";
import { TerminalOutputDecoderRegistry } from "./terminalOutput";

const MAX_BACKLOG_CHARS = 512 * 1024;
const MAX_OSC_TITLE_CHARS = 8 * 1024;
const OSC_TITLE_START_RE = /\u001b\](?:0|1|2);/g;
const OSC_PARTIAL_PREFIXES = ["\u001b", "\u001b]", "\u001b]0", "\u001b]1", "\u001b]2"] as const;

type OutputListener = (text: string) => void;
type LifecycleListener = (payload: TerminalLifecyclePayload) => void;
type TitleListener = (sessionId: string, title: string) => void;

type SessionBacklog = {
  chunks: string[];
  totalChars: number;
};

export type OscTitleScanResult = {
  titles: string[];
  carry: string;
};

/**
 * Extracts OSC 0/1/2 terminal titles from decoded PTY output while preserving an incomplete
 * sequence for the next chunk. This runs independently of xterm, so background/unmounted tabs
 * still produce activity title updates.
 */
export function scanTerminalOscTitles(text: string, carry = ""): OscTitleScanResult {
  const source = `${carry}${text}`;
  const titles: string[] = [];
  let searchFrom = 0;

  OSC_TITLE_START_RE.lastIndex = 0;
  while (true) {
    OSC_TITLE_START_RE.lastIndex = searchFrom;
    const match = OSC_TITLE_START_RE.exec(source);
    if (!match) break;

    const valueStart = match.index + match[0].length;
    const terminator = findOscTerminator(source, valueStart);
    if (!terminator) {
      return {
        titles,
        carry: source.slice(Math.max(match.index, source.length - MAX_OSC_TITLE_CHARS)),
      };
    }

    titles.push(source.slice(valueStart, terminator.index));
    searchFrom = terminator.index + terminator.length;
  }

  return { titles, carry: findPartialOscPrefix(source.slice(searchFrom)) };
}

function findOscTerminator(source: string, from: number): { index: number; length: number } | null {
  const candidates = [
    { index: source.indexOf("\u0007", from), length: 1 },
    { index: source.indexOf("\u001b\\", from), length: 2 },
    { index: source.indexOf("\u009c", from), length: 1 },
  ].filter((candidate) => candidate.index >= 0);
  if (candidates.length === 0) return null;
  return candidates.reduce((earliest, candidate) => candidate.index < earliest.index ? candidate : earliest);
}

function findPartialOscPrefix(source: string): string {
  for (const prefix of [...OSC_PARTIAL_PREFIXES].sort((a, b) => b.length - a.length)) {
    if (source.endsWith(prefix)) return prefix;
  }
  return "";
}

class TerminalEventBus {
  private readonly decoderRegistry = new TerminalOutputDecoderRegistry();
  private readonly outputListeners = new Map<string, Set<OutputListener>>();
  private readonly lifecycleListeners = new Set<LifecycleListener>();
  private readonly titleListeners = new Set<TitleListener>();
  private readonly backlog = new Map<string, SessionBacklog>();
  private readonly titleCarry = new Map<string, string>();
  private readonly lastTitle = new Map<string, string>();
  private startPromise: Promise<void> | null = null;

  ensureStarted(): Promise<void> {
    if (this.startPromise) return this.startPromise;
    this.startPromise = Promise.all([
      onTerminalOutput((payload) => this.handleOutput(payload)),
      onTerminalLifecycle((payload) => this.handleLifecycle(payload)),
    ]).then(() => undefined);
    return this.startPromise;
  }

  subscribeOutput(sessionId: string, listener: OutputListener, replay = true) {
    const listeners = this.outputListeners.get(sessionId) ?? new Set<OutputListener>();
    listeners.add(listener);
    this.outputListeners.set(sessionId, listeners);

    if (replay) {
      const existing = this.backlog.get(sessionId);
      if (existing && existing.totalChars > 0) {
        listener(existing.chunks.join(""));
      }
    }

    return () => {
      const current = this.outputListeners.get(sessionId);
      current?.delete(listener);
      if (current?.size === 0) this.outputListeners.delete(sessionId);
    };
  }

  subscribeLifecycle(listener: LifecycleListener) {
    this.lifecycleListeners.add(listener);
    return () => {
      this.lifecycleListeners.delete(listener);
    };
  }

  subscribeTitle(listener: TitleListener) {
    this.titleListeners.add(listener);
    return () => {
      this.titleListeners.delete(listener);
    };
  }

  clearSession(sessionId: string) {
    this.decoderRegistry.reset(sessionId);
    this.backlog.delete(sessionId);
    this.outputListeners.delete(sessionId);
    this.titleCarry.delete(sessionId);
    this.lastTitle.delete(sessionId);
  }

  getBacklogMetricsForTest(sessionId?: string): { sessions: number; chunks: number; chars: number } {
    if (sessionId) {
      const entry = this.backlog.get(sessionId);
      if (!entry) return { sessions: 0, chunks: 0, chars: 0 };
      return {
        sessions: 1,
        chunks: entry.chunks.length,
        chars: entry.totalChars,
      };
    }
    let totalChunks = 0;
    let totalChars = 0;
    for (const entry of this.backlog.values()) {
      totalChunks += entry.chunks.length;
      totalChars += entry.totalChars;
    }
    return {
      sessions: this.backlog.size,
      chunks: totalChunks,
      chars: totalChars,
    };
  }

  private handleOutput(payload: TerminalOutputPayload) {
    const text = this.decoderRegistry.decode(payload.sessionId, payload.data);
    if (text) this.publishOutput(payload.sessionId, text);
  }

  private handleLifecycle(payload: TerminalLifecyclePayload) {
    if (payload.state === "exited" || payload.state === "failed") {
      const tail = this.decoderRegistry.finish(payload.sessionId);
      if (tail) this.publishOutput(payload.sessionId, tail);
    }
    for (const listener of this.lifecycleListeners) listener(payload);
  }

  private publishOutput(sessionId: string, text: string) {
    const scan = scanTerminalOscTitles(text, this.titleCarry.get(sessionId) ?? "");
    if (scan.carry) this.titleCarry.set(sessionId, scan.carry);
    else this.titleCarry.delete(sessionId);

    for (const title of scan.titles) {
      if (this.lastTitle.get(sessionId) === title) continue;
      this.lastTitle.set(sessionId, title);
      for (const listener of this.titleListeners) listener(sessionId, title);
    }

    if (text.length > 0) {
      let entry = this.backlog.get(sessionId);
      if (!entry) {
        entry = { chunks: [], totalChars: 0 };
        this.backlog.set(sessionId, entry);
      }

      entry.chunks.push(text);
      entry.totalChars += text.length;

      while (entry.totalChars > MAX_BACKLOG_CHARS && entry.chunks.length > 0) {
        const oldest = entry.chunks[0];
        if (oldest === undefined) break;
        const overflow = entry.totalChars - MAX_BACKLOG_CHARS;
        if (oldest.length <= overflow) {
          entry.chunks.shift();
          entry.totalChars -= oldest.length;
        } else {
          entry.chunks[0] = oldest.slice(overflow);
          entry.totalChars -= overflow;
          break;
        }
      }
    }

    for (const listener of this.outputListeners.get(sessionId) ?? []) listener(text);
  }
}

export const terminalEventBus = new TerminalEventBus();

export function getBacklogMetricsForTest(sessionId?: string) {
  return terminalEventBus.getBacklogMetricsForTest(sessionId);
}

export function ensureTerminalEvents() {
  return terminalEventBus.ensureStarted();
}

import { useEffect, useRef, useState } from "react";

import { terminalHostManager } from "../lib/terminalHostManager";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";
import { TerminalSearchOverlay } from "./TerminalSearchOverlay";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
};

export function TerminalPane({ session, active, onBell, onTitleChange, searchOpen, onCloseSearch }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  useEffect(() => {
    return terminalHostManager.registerVisible(session.id);
  }, [session.id]);

  useEffect(() => {
    terminalHostManager.applyInstanceSettings(session.id, settings);
  }, [session.id, settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;

    void terminalHostManager
      .getOrCreate(session, active, onBell, onTitleChange)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }
        if (active) {
          instance.terminal.focus();
        }

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled && instance.element.clientWidth > 0 && instance.element.clientHeight > 0) {
            instance.fitAddon.fit();
          }
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    if (instance) {
      instance.active = active;
      if (active) {
        instance.terminal.focus();
      }
    }
  }, [active, session.id]);

  return (
    <div
      data-testid="terminal-pane-surface"
      className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
      style={{ backgroundColor: settings.theme.background }}
    >
      <div
        ref={containerRef}
        data-testid="terminal-mount"
        className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
        style={{ backgroundColor: settings.theme.background }}
      />
      {searchOpen ? (
        <TerminalSearchOverlay
          instance={terminalHostManager.getInstance(session.id)}
          onClose={onCloseSearch ?? (() => undefined)}
        />
      ) : null}
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

import { useRef, useEffect } from "react";
import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
import { BrowserToolbar } from "./BrowserToolbar";
import type { BrowserTab } from "../lib/types";

interface BrowserPaneProps {
  tab: BrowserTab;
  visible?: boolean;
  onNavigate: (url: string) => void;
  onReload: () => void;
}

export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const updateVisibility = (nextVisible: boolean) => {
      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    };

    const updateBounds = () => {
      if (!visible) {
        updateVisibility(false);
        return;
      }

      const rect = el.getBoundingClientRect();
      void setBrowserBounds(tab.browserId, {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      }).catch(() => undefined);
      updateVisibility(true);
    };

    updateBounds();

    const resizeObserver = new ResizeObserver(() => {
      updateBounds();
    });

    resizeObserver.observe(el);
    window.addEventListener("resize", updateBounds);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateBounds);
      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
      updateVisibility(false);
    };
  }, [tab.browserId, visible]);

  return (
    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
      <div
        ref={containerRef}
        data-testid="browser-viewport"
        className="flex-1 w-full bg-card relative"
      />
    </div>
  );
}

